    private EditorCommand RegisterEditorCommand(
        EditorCommandId id,
        string title,
        string description,
        string icon,
        string shortcut,
        EditorCommandCategory category,
        Action execute,
        Func<EditorCommandState>? getState = null,
        bool isDangerous = false)
    {
        return _editorCommandService.Register(new EditorCommandDefinition
        {
            Id = id,
            Title = title,
            Description = description,
            Icon = icon,
            Shortcut = shortcut,
            Category = category,
            Execute = execute,
            GetState = getState,
            IsDangerous = isDangerous
        });
    }

    private static EditorCommandState StateWhen(bool condition, string disabledReason)
    {
        return condition ? EditorCommandState.Enabled : EditorCommandState.Disabled(disabledReason);
    }

    private void RequestExternalEditorCommand(EditorCommandId id)
    {
        ExternalEditorCommandRequested?.Invoke(id);
    }

    private void WorkspaceLogService_EntryAdded(object? sender, WorkspaceLogEntryModel entry)
    {
        if (!Dispatcher.UIThread.CheckAccess())
        {
            Dispatcher.UIThread.Post(() => WorkspaceLogService_EntryAdded(sender, entry));
            return;
        }

        OutputEntries.Insert(0, entry);
        while (OutputEntries.Count > 500)
            OutputEntries.RemoveAt(OutputEntries.Count - 1);

        FilterOutputEntries();
    }

