    public void AddInteractionTrace(string eventName, string details = "", string focusedElement = "", string viewFlags = "")
    {
        if (!Dispatcher.UIThread.CheckAccess())
        {
            Dispatcher.UIThread.Post(() => AddInteractionTrace(eventName, details, focusedElement, viewFlags));
            return;
        }

        var selectedDocumentId = GetTrackedControlDocumentId(SelectedControl);
        var vmFlags =
            $"isEditingProperty={IsPropertyEditorFocused}; " +
            $"isInspectorInteractionActive={_isInspectorInteractionActive}; " +
            $"isApplyingDocument={_isApplyingDocument}; " +
            $"isDragging={ExtractTraceFlag(viewFlags, "drag")}; " +
            $"switchingForm={_isSwitchingActiveForm}; rebuildingGrid={_isRebuildingPropertyGrid}; " +
            $"pendingInspectorRebuild={_pendingInspectorRebuild}";

        if (!string.IsNullOrWhiteSpace(viewFlags))
            vmFlags += $"; view={viewFlags}";

        InteractionTraceEntries.Insert(0, new InteractionTraceEntryModel
        {
            EventName = eventName,
            ActiveForm = $"{ActiveDocumentName}/{ActiveDocumentId}",
            SelectedControl = $"{SelectedControl?.Name ?? "-"}:{SelectedControl?.Id ?? "-"} doc={selectedDocumentId}",
            FocusedElement = string.IsNullOrWhiteSpace(focusedElement) ? "-" : focusedElement,
            Flags = vmFlags,
            Details = details
        });

        while (InteractionTraceEntries.Count > 200)
            InteractionTraceEntries.RemoveAt(InteractionTraceEntries.Count - 1);
    }

    private static string ExtractTraceFlag(string viewFlags, string key)
    {
        if (string.IsNullOrWhiteSpace(viewFlags))
            return "-";

        var prefix = $"{key}:";
        var value = viewFlags
            .Split(',', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries)
            .FirstOrDefault(part => part.Contains(prefix, StringComparison.OrdinalIgnoreCase));

        if (value is null)
            return "-";

        var start = value.IndexOf(prefix, StringComparison.OrdinalIgnoreCase);
        return start < 0 ? "-" : value[(start + prefix.Length)..].Trim();
    }

    public string BuildInteractionTraceText()
    {
        return string.Join(Environment.NewLine, InteractionTraceEntries.Select(entry => entry.Summary));
    }

    public void LogWorkspace(WorkspaceLogLevel level, string category, string message, string details = "")
    {
        var entry = _workspaceLogService.Log(level, category, message, details, CurrentDocumentPath);
        AppendWorkspaceLogFile(entry);
    }

    private void AppendWorkspaceLogFile(WorkspaceLogEntryModel entry)
    {
        if (!SaveLogsToFile)
            return;

        try
        {
            var folder = string.IsNullOrWhiteSpace(LogsFolderPath)
                ? Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData), "AvaloniaUiVisualDesigner", "logs")
                : LogsFolderPath;
            Directory.CreateDirectory(folder);

            var filePath = Path.Combine(folder, $"designer-{DateTime.UtcNow:yyyyMMdd}.log");
            var line = $"[{entry.TimestampUtc:O}] [{entry.Level}] [{entry.Category}] {entry.Message}";
            if (!string.IsNullOrWhiteSpace(entry.Details))
                line += $" | {entry.Details.ReplaceLineEndings(" ")}";
            if (!string.IsNullOrWhiteSpace(entry.RelatedDocumentPath))
                line += $" | document={entry.RelatedDocumentPath}";

            File.AppendAllText(filePath, line + Environment.NewLine, Encoding.UTF8);
        }
        catch
        {
            // Logging must never break editor input, preview, export, or project operations.
        }
    }

    public void ShowWorkspaceToast(WorkspaceToastLevel level, string title, string message = "", bool isPersistent = false)
    {
        _workspaceNotificationService.Show(level, title, message, isPersistent);
    }

    public WorkspaceTaskModel StartWorkspaceTask(string title, string description = "", double? progress = null)
    {
        var task = _workspaceTaskService.Start(title, description, progress);
        LogWorkspace(WorkspaceLogLevel.Info, OutputCategoryBackgroundTasks, $"Started: {title}", description);
        return task;
    }

    public void ReportWorkspaceTask(WorkspaceTaskModel? task, double? progress = null, string statusMessage = "")
    {
        _workspaceTaskService.Report(task, progress, statusMessage);
    }

    public void CompleteWorkspaceTask(WorkspaceTaskModel? task, string statusMessage = "Completed")
    {
        _workspaceTaskService.Complete(task, statusMessage);
        if (task is not null)
            LogWorkspace(WorkspaceLogLevel.Success, OutputCategoryBackgroundTasks, $"Completed: {task.Title}", statusMessage);
    }

    public void FailWorkspaceTask(WorkspaceTaskModel? task, string errorMessage)
    {
        _workspaceTaskService.Fail(task, errorMessage);
        if (task is not null)
            LogWorkspace(WorkspaceLogLevel.Error, OutputCategoryBackgroundTasks, $"Failed: {task.Title}", errorMessage);
    }

    public void SetEditorZoom(double zoom)
    {
        EditorZoom = Math.Clamp(zoom, 0.1, 4.0);
    }

    public void ToggleRecentFilePinned(RecentFileModel? file)
    {
        if (file is null)
            return;

        file.IsPinned = !file.IsPinned;
        var path = file.FilePath;
        var items = RecentFiles
            .OrderByDescending(item => item.IsPinned)
            .ThenByDescending(item => item.LastOpenedUtc)
            .ToList();
        RecentFiles.Clear();
        foreach (var item in items)
            RecentFiles.Add(item);

        StatusText = file.IsPinned ? $"Pinned recent file: {file.Title}" : $"Unpinned recent file: {file.Title}";
        LogWorkspace(WorkspaceLogLevel.Info, OutputCategoryGeneral, StatusText, path);
    }

    private void FilterOutputEntries()
    {
        var selectedCategory = SelectedOutputCategory;
        var filtered = OutputEntries
            .Where(entry => string.Equals(selectedCategory, OutputCategoryAll, StringComparison.OrdinalIgnoreCase)
                || string.Equals(entry.Category, selectedCategory, StringComparison.OrdinalIgnoreCase))
            .ToList();

        FilteredOutputEntries.Clear();
        foreach (var entry in filtered)
            FilteredOutputEntries.Add(entry);

        OnPropertyChanged(nameof(HasFilteredOutputEntries));
        OnPropertyChanged(nameof(HasNoFilteredOutputEntries));
        OnPropertyChanged(nameof(OutputFilterSummary));
    }

    public EditorCommand? GetEditorCommand(EditorCommandId id)
    {
        return _editorCommandService.Find(id);
    }

    public bool TryExecuteEditorCommand(EditorCommandId id)
    {
        var executed = _editorCommandService.TryExecute(id);
        RefreshEditorCommands();
        return executed;
    }

    public void RefreshEditorCommands()
    {
        _editorCommandService.Refresh();
        if (IsCommandPaletteOpen)
            RefreshCommandPaletteCommands();
    }

    private void ScheduleEditorCommandRefresh()
    {
        _isEditorCommandRefreshScheduled = true;
        _editorCommandRefreshTimer.Stop();
        _editorCommandRefreshTimer.Start();
    }

    private void EditorCommandRefreshTimer_Tick(object? sender, EventArgs e)
    {
        _editorCommandRefreshTimer.Stop();
        if (!_isEditorCommandRefreshScheduled)
            return;

        _isEditorCommandRefreshScheduled = false;
        if (IsPropertyEditorFocused)
        {
            _isEditorCommandRefreshScheduled = true;
            _editorCommandRefreshTimer.Start();
            return;
        }

        RefreshEditorCommands();
    }

    private void RaiseEditorCommandProperties()
    {
        OnPropertyChanged(nameof(NewEditorCommand));
        OnPropertyChanged(nameof(NewProjectEditorCommand));
        OnPropertyChanged(nameof(OpenEditorCommand));
        OnPropertyChanged(nameof(OpenProjectEditorCommand));
        OnPropertyChanged(nameof(SaveEditorCommand));
        OnPropertyChanged(nameof(SaveProjectEditorCommand));
        OnPropertyChanged(nameof(SaveAsEditorCommand));
        OnPropertyChanged(nameof(UndoEditorCommand));
        OnPropertyChanged(nameof(RedoEditorCommand));
        OnPropertyChanged(nameof(DeleteEditorCommand));
        OnPropertyChanged(nameof(DuplicateEditorCommand));
        OnPropertyChanged(nameof(CopyEditorCommand));
        OnPropertyChanged(nameof(PasteEditorCommand));
        OnPropertyChanged(nameof(GroupEditorCommand));
        OnPropertyChanged(nameof(UngroupEditorCommand));
