    }

    private DesignControlModel? GetActiveLayoutHost()
    {
        if (SelectedControl is not null && CanHostChildren(SelectedControl))
            return SelectedControl;

        if (SelectedControl is not null)
            return GetControl(SelectedControl.ParentId);

        return null;
    }

    private string GetActiveLayoutMode()
    {
        var host = GetActiveLayoutHost();
        return host is null
            ? DesignerLayoutModes.NormalizeMode(SurfaceLayoutMode)
            : GetLayoutModeForControl(host);
    }

    private string GetActiveLayoutOrientation()
    {
        var host = GetActiveLayoutHost();
        return host is null
            ? DesignerLayoutModes.NormalizeOrientation(SurfaceLayoutOrientation)
            : DesignerLayoutModes.NormalizeOrientation(host.LayoutOrientation);
    }

    private double GetActiveLayoutSpacing()
    {
        var host = GetActiveLayoutHost();
        return Math.Max(0, host?.LayoutSpacing ?? SurfaceLayoutSpacing);
    }

    private int GetActiveLayoutColumns()
    {
        var host = GetActiveLayoutHost();
        return Math.Max(1, host?.Columns ?? SurfaceLayoutColumns);
    }

    private int GetActiveLayoutRows()
    {
        var host = GetActiveLayoutHost();
        return Math.Max(1, host?.Rows ?? SurfaceLayoutRows);
    }

    private string GetActiveGridColumnDefinitions()
    {
        var host = GetActiveLayoutHost();
        return host?.GridColumnDefinitions ?? SurfaceGridColumnDefinitions;
    }

    private string GetActiveGridRowDefinitions()
    {
        var host = GetActiveLayoutHost();
        return host?.GridRowDefinitions ?? SurfaceGridRowDefinitions;
    }

    private IReadOnlyList<DesignControlModel> GetActiveLayoutChildren()
    {
        return GetChildControls(GetActiveLayoutHost()?.Id).ToList();
    }

    private void SetActiveLayoutMode(string layoutMode)
    {
        var normalized = DesignerLayoutModes.NormalizeMode(layoutMode);
        var host = GetActiveLayoutHost();

        BeginUndoBatch();
        try
        {
            if (host is null)
            {
                SurfaceLayoutMode = normalized;
                if (normalized == DesignerLayoutModes.Grid)
                {
                    SurfaceLayoutColumns = Math.Max(1, SurfaceLayoutColumns);
                    SurfaceLayoutRows = Math.Max(1, SurfaceLayoutRows);
                }
            }
            else
            {
                host.ChildLayoutMode = normalized;
                if (normalized == DesignerLayoutModes.Grid)
                {
                    host.Columns = Math.Max(1, host.Columns);
                    host.Rows = Math.Max(1, host.Rows);
                    host.ShowGridLines = true;
                }
            }

            NormalizeActiveStackOrders();
            RebuildLayoutDefinitionEditor();
            RaiseActiveLayoutProperties();
            NotifyDesignerStateChanged();
        }
        finally
        {
            CommitUndoBatch();
        }
    }

    private void SetActiveLayoutOrientation(string value)
    {
        var normalized = DesignerLayoutModes.NormalizeOrientation(value);
        var host = GetActiveLayoutHost();
        if (host is null)
            SurfaceLayoutOrientation = normalized;
        else
            host.LayoutOrientation = normalized;

        RaiseActiveLayoutProperties();
        NotifyDesignerStateChanged();
    }

    private void SetActiveLayoutSpacing(double value)
    {
        var normalized = Math.Max(0, value);
        var host = GetActiveLayoutHost();
        if (host is null)
            SurfaceLayoutSpacing = normalized;
        else
            host.LayoutSpacing = normalized;

        RaiseActiveLayoutProperties();
        NotifyDesignerStateChanged();
    }

    private void RaiseActiveLayoutProperties()
    {
        OnPropertyChanged(nameof(ActiveLayoutHost));
        OnPropertyChanged(nameof(IsActiveLayoutRoot));
        OnPropertyChanged(nameof(ActiveLayoutHostTitle));
        OnPropertyChanged(nameof(ActiveLayoutMode));
        OnPropertyChanged(nameof(IsActiveLayoutGrid));
        OnPropertyChanged(nameof(IsActiveLayoutStack));
        OnPropertyChanged(nameof(IsActiveLayoutFlow));
        OnPropertyChanged(nameof(IsLayoutOverlayVisible));
        OnPropertyChanged(nameof(ActiveLayoutOverlayTitle));
        OnPropertyChanged(nameof(ActiveLayoutOverlaySummary));
        OnPropertyChanged(nameof(ActiveGridDefinitionsPreview));
        OnPropertyChanged(nameof(ActiveStackOrientation));
        OnPropertyChanged(nameof(ActiveStackSpacing));
        OnPropertyChanged(nameof(HasLayoutGridRows));
        OnPropertyChanged(nameof(HasLayoutGridColumns));
    }

    public bool IsControlSelected(DesignControlModel? control)
    {
        return control is not null && SelectedControlIds.Contains(control.Id);
    }

    public IReadOnlyList<DesignControlModel> GetSelectedControls()
    {
        return SelectedControlIds
            .Select(GetControl)
            .Where(control => control is not null)
            .Cast<DesignControlModel>()
            .ToList();
    }

    public IReadOnlyList<DesignControlModel> GetEditableSelectedControls()
    {
        return GetSelectedControls()
            .Where(control => !control.IsLocked)
            .ToList();
    }

    public IReadOnlyList<DesignControlModel> GetEditableSelectedRootControls()
    {
        var selected = GetEditableSelectedControls();
        return selected
            .Where(control => !selected.Any(other => other.Id != control.Id && IsDescendant(control.ParentId, other.Id)))
            .ToList();
    }

    public IReadOnlyList<DesignControlModel> GetVisibleEditableSelectedControls()
    {
        return GetSelectedControls()
            .Where(control => control.IsVisible && !control.IsLocked)
            .ToList();
    }

    public IReadOnlyList<DesignControlModel> GetVisibleEditableSelectedRootControls()
    {
        var selected = GetVisibleEditableSelectedControls();
        return selected
            .Where(control => !selected.Any(other => other.Id != control.Id && IsDescendant(control.ParentId, other.Id)))
            .ToList();
    }

    public void ApplyToSelectedControls(Action<DesignControlModel> apply, bool rootsOnly = false)
    {
        var targets = rootsOnly ? GetSelectedRootControls() : GetSelectedControls();
        foreach (var control in targets)
            apply(control);
    }

    public void SelectSingleControl(DesignControlModel? control)
    {
        SetSelection(control is null ? Array.Empty<DesignControlModel>() : new[] { control }, control);
    }

    public void SelectControls(IEnumerable<DesignControlModel> controls, DesignControlModel? primaryControl = null)
    {
        var selected = controls
            .Where(control => control is not null)
            .DistinctBy(control => control.Id)
            .ToList();

        var primary = primaryControl is not null && selected.Any(control => control.Id == primaryControl.Id)
            ? primaryControl
            : selected.LastOrDefault();

        SetSelection(selected, primary);
    }

    public void ToggleControlSelection(DesignControlModel control)
    {
        var selected = GetSelectedControls().ToList();

        if (selected.Any(item => item.Id == control.Id))
            selected.RemoveAll(item => item.Id == control.Id);
        else
            selected.Add(control);

        var primary = selected.LastOrDefault();
        SetSelection(selected, primary);
    }

    public void ClearSelection()
    {
        TraceDocumentDebug(
            "ClearSelection",
            $"old={SelectedControl?.Name ?? "-"}:{SelectedControl?.Id ?? "-"}; active={ActiveDocumentId}; canvas={CanvasRenderedDocumentId}",
            toOutput: false);
        SetSelection(Array.Empty<DesignControlModel>(), null);
    }

    public void SelectAllControls()
    {
        var controls = Controls
            .Where(control => control.IsVisible && !control.IsLocked)
            .ToList();
        SetSelection(controls, controls.LastOrDefault());
    }

    private void RebuildStructureTree()
    {
        if (_isStructureTreeRefreshSuspended)
            return;

        var stopwatch = Stopwatch.StartNew();
        var previousExpandedIds = EnumerateStructureTreeItems()
            .Where(item => item.IsExpanded)
            .Select(item => item.Id)
            .ToHashSet(StringComparer.OrdinalIgnoreCase);
        var query = StructureSearchText.Trim();
        var hasSearch = !string.IsNullOrWhiteSpace(query);
        var source = Controls.ToList();
        var validIds = source
            .Select(control => control.Id)
            .ToHashSet(StringComparer.OrdinalIgnoreCase);

        var childrenByParent = source
            .GroupBy(control =>
            {
                var parentId = NormalizeId(control.ParentId);
                return validIds.Contains(parentId) ? parentId : "";
            }, StringComparer.OrdinalIgnoreCase)
            .ToDictionary(group => group.Key, group => group.ToList(), StringComparer.OrdinalIgnoreCase);
        _structureTreeItemsByControlId.Clear();

        var root = new StructureTreeItemModel(
            control: null,
            id: "form-root",
            name: string.IsNullOrWhiteSpace(FormTitle) ? "Form" : FormTitle,
            type: "Form",
            text: "",
            isContainer: true,
            isGroup: false,
            isHidden: false,
            isLocked: false);
        root.IsExpanded = true;
        root.IsSearchMatch = hasSearch && MatchesStructureSearch(root.Name, root.Type, root.Text, query);

        var visitedIds = new HashSet<string>(StringComparer.OrdinalIgnoreCase);

        StructureTreeItemModel? BuildNode(DesignControlModel control)
        {
            if (!visitedIds.Add(control.Id))
                return null;

            var node = CreateStructureNode(control);
            node.IsExpanded = hasSearch
                || node.IsContainer
                || previousExpandedIds.Count == 0
                || previousExpandedIds.Contains(node.Id);
            node.IsSearchMatch = hasSearch && MatchesStructureSearch(control.Name, control.Type, control.Text, query);

            if (childrenByParent.TryGetValue(control.Id, out var children))
            {
                foreach (var child in children)
                {
                    var childNode = BuildNode(child);
                    if (childNode is not null)
                        node.Children.Add(childNode);
                }
            }

            var shouldInclude = !hasSearch || node.IsSearchMatch || node.Children.Count > 0;
            if (shouldInclude)
                _structureTreeItemsByControlId[control.Id] = node;

            return shouldInclude ? node : null;
        }

        void AddChildren(StructureTreeItemModel parentNode, string parentId)
        {
            if (!childrenByParent.TryGetValue(parentId, out var children))
                return;

            foreach (var child in children)
            {
                var childNode = BuildNode(child);
                if (childNode is not null)
                    parentNode.Children.Add(childNode);
            }
        }

        AddChildren(root, "");

        foreach (var orphan in source.Where(control => !visitedIds.Contains(control.Id)))
        {
            var orphanNode = BuildNode(orphan);
            if (orphanNode is not null)
                root.Children.Add(orphanNode);
        }

        StructureTreeItems.Clear();
        StructureTreeItems.Add(root);
        ApplyStructureDiagnosticsBadges();
        RefreshStructureSelection();
        RaiseStructureTreeProperties();
        stopwatch.Stop();
        _lastStructureTreeRebuildMs = stopwatch.Elapsed.TotalMilliseconds;
        ReportPerformanceMetric("StructureTree rebuild", _lastStructureTreeRebuildMs);
        OnPropertyChanged(nameof(PerformanceDiagnosticsSummary));
    }

    private StructureTreeItemModel CreateStructureNode(DesignControlModel control)
    {
        var isGroup = string.Equals(control.Type, DesignerControlTypes.Group, StringComparison.OrdinalIgnoreCase);
        var isMissingPlugin = !_registry.TryGetControl(control.Type, out _);
        return new StructureTreeItemModel(
            control,
            control.Id,
            control.Name,
            control.Type,
            control.Text,
            CanHostChildren(control),
            isGroup,
            !control.IsVisible,
            control.IsLocked,
            isMissingPlugin);
    }

    private static bool MatchesStructureSearch(string name, string type, string text, string query)
    {
        return name.Contains(query, StringComparison.OrdinalIgnoreCase)
            || type.Contains(query, StringComparison.OrdinalIgnoreCase)
            || (!string.IsNullOrWhiteSpace(text) && text.Contains(query, StringComparison.OrdinalIgnoreCase));
    }

    private void RefreshStructureSelection()
    {
        var selectedIds = SelectedControlIds.ToHashSet(StringComparer.OrdinalIgnoreCase);
        StructureTreeItemModel? selectedItem = null;
        var primaryId = SelectedControl?.Id ?? "";

        foreach (var item in EnumerateStructureTreeItems())
        {
            var isSelected = item.Control is not null && selectedIds.Contains(item.Control.Id);
            item.IsSelected = isSelected;

            if (item.Control is not null
                && !string.IsNullOrWhiteSpace(primaryId)
                && string.Equals(item.Control.Id, primaryId, StringComparison.OrdinalIgnoreCase))
            {
                selectedItem = item;
            }
            else if (selectedItem is null && isSelected)
            {
                selectedItem = item;
            }
        }

        selectedItem ??= StructureTreeItems.FirstOrDefault();

        _isUpdatingStructureSelection = true;
        try
        {
            SelectedStructureItem = selectedItem;
        }
        finally
        {
            _isUpdatingStructureSelection = false;
        }

        RaiseStructureTreeProperties();
    }

    private IEnumerable<StructureTreeItemModel> EnumerateStructureTreeItems()
    {
        foreach (var root in StructureTreeItems)
        {
            yield return root;

            foreach (var child in EnumerateStructureTreeItems(root))
                yield return child;
        }
    }

    private static IEnumerable<StructureTreeItemModel> EnumerateStructureTreeItems(StructureTreeItemModel parent)
    {
        foreach (var child in parent.Children)
        {
            yield return child;

            foreach (var descendant in EnumerateStructureTreeItems(child))
                yield return descendant;
        }
    }

    private void RaiseStructureTreeProperties()
    {
        OnPropertyChanged(nameof(HasStructureTreeControls));
        OnPropertyChanged(nameof(HasNoStructureTreeControls));
        OnPropertyChanged(nameof(HasStructureSearchText));
        OnPropertyChanged(nameof(IsStructureTreeEmptyStateVisible));
        OnPropertyChanged(nameof(StructureTreeEmptyText));
        OnPropertyChanged(nameof(StructureTreeSummary));
    }

    private void ScheduleStructureTreeSearchRefresh()
    {
        _isStructureTreeSearchRefreshScheduled = true;
        _scheduledStructureSearchSessionId = DocumentSessionId;
        _structureTreeSearchRefreshTimer.Stop();
        _structureTreeSearchRefreshTimer.Start();
    }

    private void StructureTreeSearchRefreshTimer_Tick(object? sender, EventArgs e)
    {
        _structureTreeSearchRefreshTimer.Stop();
        if (!_isStructureTreeSearchRefreshScheduled)
            return;

        _isStructureTreeSearchRefreshScheduled = false;
        if (!string.Equals(_scheduledStructureSearchSessionId, DocumentSessionId, StringComparison.Ordinal))
            return;

        RebuildStructureTree();
    }

    private void ApplyStructureDiagnosticsBadges()
    {
        var diagnosticsByControlId = Diagnostics
            .Where(diagnostic => !string.IsNullOrWhiteSpace(diagnostic.RelatedControlId))
            .GroupBy(diagnostic => diagnostic.RelatedControlId, StringComparer.OrdinalIgnoreCase)
            .ToDictionary(
                group => group.Key,
                group => new
                {
                    Errors = group.Count(item => item.Severity == DocumentDiagnosticSeverity.Error),
                    Warnings = group.Count(item => item.Severity == DocumentDiagnosticSeverity.Warning)
                },
                StringComparer.OrdinalIgnoreCase);

        foreach (var item in EnumerateStructureTreeItems())
        {
            if (item.Control is null || !diagnosticsByControlId.TryGetValue(item.Control.Id, out var counts))
            {
                item.DiagnosticErrorCount = 0;
                item.DiagnosticWarningCount = 0;
                continue;
            }

            item.DiagnosticErrorCount = counts.Errors;
            item.DiagnosticWarningCount = counts.Warnings;
        }
    }

    private void RefreshStructureNode(DesignControlModel control)
    {
        if (!_structureTreeItemsByControlId.TryGetValue(control.Id, out var item))
        {
            RebuildStructureTree();
            return;
        }

        item.Name = control.Name;
        item.Text = control.Text;
        item.IsHidden = !control.IsVisible;
        item.IsLocked = control.IsLocked;
        RaiseStructureTreeProperties();
    }

    private static bool IsStructureTreeProperty(string? propertyName)
    {
        return propertyName is nameof(DesignControlModel.Name)
            or nameof(DesignControlModel.Type)
            or nameof(DesignControlModel.Text)
            or nameof(DesignControlModel.ParentId)
            or nameof(DesignControlModel.IsVisible)
            or nameof(DesignControlModel.IsLocked);
    }

    private static bool RequiresStructureTreeRebuild(string? propertyName)
    {
        return propertyName is nameof(DesignControlModel.ParentId)
            or nameof(DesignControlModel.Type);
    }

    [RelayCommand]
    public void RefreshDiagnostics()
    {
        RefreshDiagnosticsNow();
    }

    private void ScheduleDiagnosticsRefresh()
    {
        _isDiagnosticsRefreshScheduled = true;
        _scheduledDiagnosticsSessionId = DocumentSessionId;
        _diagnosticsRefreshTimer.Stop();
        _diagnosticsRefreshTimer.Start();
    }

    private void DiagnosticsRefreshTimer_Tick(object? sender, EventArgs e)
    {
        _diagnosticsRefreshTimer.Stop();
        if (!_isDiagnosticsRefreshScheduled)
            return;

        _isDiagnosticsRefreshScheduled = false;
        if (IsPropertyEditorFocused)
        {
            _isDiagnosticsRefreshScheduled = true;
            _diagnosticsRefreshTimer.Start();
            return;
        }

        if (!string.Equals(_scheduledDiagnosticsSessionId, DocumentSessionId, StringComparison.Ordinal))
            return;

        RefreshDiagnosticsNow();
    }

    private void RefreshDiagnosticsNow()
    {
        TrackRefreshOperation(nameof(RefreshDiagnosticsNow), "ScheduledDiagnostics");
        var stopwatch = Stopwatch.StartNew();
        var memoryBefore = GC.GetTotalMemory(forceFullCollection: false);
        var diagnostics = _diagnosticsService
            .Validate(Controls, BindingSources, Interactions, CurrentDocumentPath, DesignWidth, DesignHeight, SurfaceLayoutMode, SurfaceLayoutColumns, SurfaceLayoutRows)
            .ToList();
        AppendPluginLoaderDiagnostics(diagnostics);
        AppendProjectInteractionDiagnostics(diagnostics);
        AppendExportDiagnostics(diagnostics);
        AppendPreviewRuntimeDiagnostics(diagnostics);
        AppendDocumentIsolationDiagnostics(diagnostics);

        if (DiagnosticsMatch(Diagnostics, diagnostics))
        {
            RaiseDiagnosticsProperties();
            ScheduleExportChecklistRefresh();
            stopwatch.Stop();
            _lastDiagnosticsRefreshMs = stopwatch.Elapsed.TotalMilliseconds;
            TracePerfOperationEnd(
                nameof(RefreshDiagnosticsNow),
                stopwatch,
                "NoChanges",
                $"diagnostics={diagnostics.Count}",
                memoryBefore);
            OnPropertyChanged(nameof(PerformanceDiagnosticsSummary));
            return;
        }

        _isUpdatingDiagnosticsCollection = true;
        try
        {
            Diagnostics.Clear();
            foreach (var diagnostic in diagnostics)
                Diagnostics.Add(diagnostic);
        }
        finally
        {
            _isUpdatingDiagnosticsCollection = false;
        }

        RaiseDiagnosticsProperties();
        ScheduleExportChecklistRefresh();
        stopwatch.Stop();
        _lastDiagnosticsRefreshMs = stopwatch.Elapsed.TotalMilliseconds;
        ReportPerformanceMetric("Diagnostics refresh", _lastDiagnosticsRefreshMs);
        TracePerfOperationEnd(
            nameof(RefreshDiagnosticsNow),
            stopwatch,
            "Updated",
            $"diagnostics={diagnostics.Count}",
            memoryBefore);
        LogWorkspace(
            HasDiagnosticErrors ? WorkspaceLogLevel.Error : HasDiagnosticWarnings ? WorkspaceLogLevel.Warning : WorkspaceLogLevel.Info,
            OutputCategoryDiagnostics,
            $"Diagnostics refreshed: errors {DiagnosticErrorCount}, warnings {DiagnosticWarningCount}, hints {DiagnosticInfoCount}.");
        OnPropertyChanged(nameof(PerformanceDiagnosticsSummary));
    }

    private void AppendDocumentIsolationDiagnostics(List<DocumentDiagnosticModel> diagnostics)
    {
        var activeControlIds = Controls.Select(control => control.Id).ToHashSet(StringComparer.OrdinalIgnoreCase);
        if (SelectedControl is not null && !activeControlIds.Contains(SelectedControl.Id))
        {
            diagnostics.Add(new DocumentDiagnosticModel
            {
                Severity = DocumentDiagnosticSeverity.Error,
                Source = "Document isolation",
                Category = "Document isolation",
                Message = "Выделенный элемент не принадлежит активной форме.",
                Recommendation = "Переключите форму ещё раз или очистите выделение. Это состояние не должно попадать в обычный workflow.",
                RelatedControlId = SelectedControl.Id,
                RelatedControlName = SelectedControl.Name
            });
        }

        foreach (var staleSelectionId in SelectedControlIds.Where(id => !activeControlIds.Contains(id)).Distinct(StringComparer.OrdinalIgnoreCase))
        {
            diagnostics.Add(new DocumentDiagnosticModel
            {
                Severity = DocumentDiagnosticSeverity.Error,
                Source = "Document isolation",
                Category = "Document isolation",
                Message = $"Selection содержит элемент другой формы: {staleSelectionId}.",
                Recommendation = "Состояние выделения будет сброшено при следующем переключении формы.",
                RelatedControlId = staleSelectionId
            });
        }

        if (SelectedBindingSource is not null
            && BindingSources.All(source => !string.Equals(source.Id, SelectedBindingSource.Id, StringComparison.OrdinalIgnoreCase)))
        {
            diagnostics.Add(new DocumentDiagnosticModel
            {
                Severity = DocumentDiagnosticSeverity.Error,
                Source = "Document isolation",
                Category = "Document isolation",
                Message = "Выбранный BindingSource не принадлежит активной форме.",
                Recommendation = "Откройте вкладку Data для активной формы и выберите источник заново.",
                RelatedBindingSourceId = SelectedBindingSource.Id,
                RelatedBindingSourceName = SelectedBindingSource.Name
            });
        }

        if (SelectedInteraction is not null
            && Interactions.All(interaction => !string.Equals(interaction.Id, SelectedInteraction.Id, StringComparison.OrdinalIgnoreCase)))
        {
            diagnostics.Add(new DocumentDiagnosticModel
            {
                Severity = DocumentDiagnosticSeverity.Error,
                Source = "Document isolation",
                Category = "Document isolation",
                Message = "Выбранное interaction-правило не принадлежит активной форме.",
                Recommendation = "Перейдите на вкладку Logic активной формы и выберите правило заново."
            });
        }

        foreach (var form in CurrentProject.Forms)
        {
            foreach (var duplicateNameGroup in form.Document.Controls
                         .Where(control => !string.IsNullOrWhiteSpace(control.Name))
                         .GroupBy(control => control.Name.Trim(), StringComparer.OrdinalIgnoreCase)
                         .Where(group => group.Count() > 1))
            {
                diagnostics.Add(new DocumentDiagnosticModel
                {
                    Severity = DocumentDiagnosticSeverity.Error,
                    Source = "Document isolation",
                    Category = "Document isolation",
                    Message = $"Форма {form.DisplayName} содержит дублирующееся имя control: {duplicateNameGroup.Key}.",
                    Recommendation = "Имена должны быть уникальны внутри одной формы. Одинаковые имена на разных формах допустимы.",
                    RelatedControlId = duplicateNameGroup.FirstOrDefault()?.Id ?? "",
                    RelatedControlName = duplicateNameGroup.Key
                });
            }

            foreach (var duplicateGroup in form.Document.Controls
                         .Where(control => !string.IsNullOrWhiteSpace(control.Id))
                         .GroupBy(control => control.Id, StringComparer.OrdinalIgnoreCase)
                         .Where(group => group.Count() > 1))
            {
                diagnostics.Add(new DocumentDiagnosticModel
                {
                    Severity = DocumentDiagnosticSeverity.Error,
                    Source = "Document isolation",
                    Category = "Document isolation",
                    Message = $"Форма {form.DisplayName} содержит дублирующийся ControlId: {duplicateGroup.Key}.",
                    Recommendation = "Дублируйте или пересоздайте элемент, чтобы получить уникальные id.",
                    RelatedControlId = duplicateGroup.Key,
                    RelatedControlName = duplicateGroup.FirstOrDefault()?.Name ?? ""
                });
            }
        }
    }

    private static bool DiagnosticsMatch(IReadOnlyCollection<DocumentDiagnosticModel> current, IReadOnlyList<DocumentDiagnosticModel> next)
    {
        if (current.Count != next.Count)
            return false;

        return current.Zip(next).All(pair => DiagnosticSignature(pair.First) == DiagnosticSignature(pair.Second));
    }

    private static string DiagnosticSignature(DocumentDiagnosticModel diagnostic)
    {
        return string.Join("|",
            diagnostic.Severity,
            diagnostic.Source ?? "",
            diagnostic.Category ?? "",
            diagnostic.RelatedControlId ?? "",
            diagnostic.Message ?? "",
            diagnostic.Recommendation ?? "");
    }

    private static void ReportPerformanceMetric(string name, double elapsedMs)
    {
        if (elapsedMs < 16)
            return;

        Debug.WriteLine($"[FormDesigner:Perf] {name}: {elapsedMs:0.0} ms");
    }

    private void TrackRefreshOperation(string operation, string reason)
    {
        if (string.IsNullOrWhiteSpace(operation))
            return;

        var now = DateTime.UtcNow;
        if (!_refreshOperationTimestamps.TryGetValue(operation, out var timestamps))
        {
            timestamps = new Queue<DateTime>();
            _refreshOperationTimestamps[operation] = timestamps;
        }

        timestamps.Enqueue(now);
        while (timestamps.Count > 0 && now - timestamps.Peek() > RefreshStormWindow)
            timestamps.Dequeue();

        if (timestamps.Count == RefreshStormThreshold)
        {
            TraceDocumentDebug(
                "REFRESH_STORM_DETECTED",
                $"operation={operation}; count={timestamps.Count}; windowMs={RefreshStormWindow.TotalMilliseconds:0}; reason={reason}; caller={operation}",
                toOutput: true,
                warning: true);
        }
    }

    private void TracePerfOperationEnd(string operation, Stopwatch stopwatch, string reason, string details = "", long? memoryBefore = null)
    {
        stopwatch.Stop();
        var memoryAfter = GC.GetTotalMemory(forceFullCollection: false);
        var allocationDetails = memoryBefore.HasValue
            ? $"; memoryBefore={memoryBefore.Value}; memoryAfter={memoryAfter}; memoryDelta={memoryAfter - memoryBefore.Value}"
            : $"; memory={memoryAfter}";

        AddInteractionTrace(
            "PERF_OPERATION_END",
            $"operation={operation}; elapsed={stopwatch.Elapsed.TotalMilliseconds:0.0}ms; reason={reason}; {details}{allocationDetails}");

        if (stopwatch.Elapsed.TotalMilliseconds >= HeavyUiOperationThresholdMs)
        {
            TraceDocumentDebug(
                "HEAVY_OPERATION_ON_UI_THREAD",
                $"operation={operation}; elapsed={stopwatch.Elapsed.TotalMilliseconds:0.0}ms; reason={reason}; {details}",
                toOutput: true,
                warning: true);
        }
    }

    public void ReportMemorySnapshot(string reason, bool forceFullCollection = false)
    {
        var memory = GC.GetTotalMemory(forceFullCollection);
        var controlsCount = Controls.Count;
        var projectControlsCount = CurrentProject.Forms.Sum(form => form.Document?.Controls.Count ?? 0);
        var propertyRowsCount = PropertyGridCategories.Sum(category => category.Rows.Count);
        var schemaCount = BindingSources.Sum(source => source.Fields.Count);
        var exportCacheCount = GeneratedFiles.Count + RequiredPackages.Count + ExportDiagnostics.Count;
        var undoRedoCount = _undoStack.Count + _redoStack.Count;

        TraceDocumentDebug(
            "MEMORY_SNAPSHOT",
            $"reason={reason}; memory={memory}; forms={CurrentProject.Forms.Count}; controls={controlsCount}; projectControls={projectControlsCount}; wrappers={_lastCanvasWrapperCount}; " +
            $"propertyRows={propertyRowsCount}; loadedDll={ImportedDllCatalog.Count}; dataSources={BindingSources.Count}; schemaCache={schemaCount}; previewRows={_lastPreviewRowsCount}; " +
            $"exportCache={exportCacheCount}; undoRedo={undoRedoCount}",
            toOutput: true);
    }

    public void RecordCanvasRenderStats(int wrapperCount, int previewRowsCount, string reason)
    {
        _lastCanvasWrapperCount = Math.Max(0, wrapperCount);
        _lastPreviewRowsCount = Math.Max(0, previewRowsCount);
        TrackRefreshOperation("RenderCanvas", reason);
    }

    private void AppendPluginLoaderDiagnostics(ICollection<DocumentDiagnosticModel> diagnostics)
    {
        if (_registry is not DesignerRegistry registry)
            return;

        foreach (var report in registry.GetPluginLoadReports()
                     .Where(report => report.Status is PluginLoadStatus.Warning or PluginLoadStatus.Error))
        {
            var details = report.Errors.Concat(report.Warnings).ToList();
            diagnostics.Add(new DocumentDiagnosticModel
            {
                Severity = report.Status == PluginLoadStatus.Error
                    ? DocumentDiagnosticSeverity.Error
                    : DocumentDiagnosticSeverity.Warning,
                Source = report.DisplayName,
                Category = "Plugin loading",
                Message = report.Message,
                Recommendation = details.Count == 0
                    ? "Проверьте DLL во вкладке Plugins."
                    : string.Join(Environment.NewLine, details)
            });
        }
    }

    public void SetPreviewRuntimeDiagnostics(IEnumerable<DocumentDiagnosticModel> diagnostics)
    {
        _previewRuntimeDiagnostics.Clear();
        _previewRuntimeDiagnostics.AddRange(diagnostics);
        RefreshDiagnostics();
    }

    public void ClearPreviewRuntimeDiagnostics()
    {
        if (_previewRuntimeDiagnostics.Count == 0)
            return;

        _previewRuntimeDiagnostics.Clear();
        RefreshDiagnostics();
    }

    private void AppendPreviewRuntimeDiagnostics(ICollection<DocumentDiagnosticModel> diagnostics)
    {
        foreach (var diagnostic in _previewRuntimeDiagnostics)
            diagnostics.Add(diagnostic);
    }

    private void AppendProjectInteractionDiagnostics(ICollection<DocumentDiagnosticModel> diagnostics)
    {
        foreach (var context in EnumerateProjectOpenFormInteractions())
        {
            var targetForm = CurrentProject.Forms.FirstOrDefault(form =>
                string.Equals(form.Id, context.TargetFormId, StringComparison.OrdinalIgnoreCase));

            if (targetForm is null)
            {
                diagnostics.Add(new DocumentDiagnosticModel
                {
                    Severity = DocumentDiagnosticSeverity.Error,
                    Source = context.SourceDisplayName,
                    Category = "Logic",
                    Message = $"OpenForm target form not found in {context.FormDisplayName}: '{context.TargetFormName}'.",
                    Recommendation = "Choose an existing target form or remove the stale OpenForm interaction.",
                    RelatedControlId = context.SourceControlId,
                    RelatedControlName = context.SourceControlName
                });
                continue;
            }

            if (string.Equals(targetForm.Id, context.FormId, StringComparison.OrdinalIgnoreCase))
            {
                diagnostics.Add(new DocumentDiagnosticModel
                {
                    Severity = DocumentDiagnosticSeverity.Warning,
                    Source = context.SourceDisplayName,
                    Category = "Logic",
                    Message = $"OpenForm points to its own form '{targetForm.DisplayName}'.",
                    Recommendation = "Usually OpenForm should target another form.",
                    RelatedControlId = context.SourceControlId,
                    RelatedControlName = context.SourceControlName
                });
            }
        }

        foreach (var conflict in GetSanitizedFormClassConflicts())
        {
            diagnostics.Add(new DocumentDiagnosticModel
            {
                Severity = DocumentDiagnosticSeverity.Error,
                Source = "Export",
                Category = "Export",
                Message = $"Form class name conflict after sanitize: {conflict}.",
                Recommendation = "Rename forms to unique C# class names. Export will append a suffix until then."
            });
        }

        foreach (var form in CurrentProject.Forms)
        {
            var sanitized = SanitizeIdentifier(form.DisplayName, "Form");
            if (string.Equals(form.DisplayName, sanitized, StringComparison.Ordinal))
                continue;

            diagnostics.Add(new DocumentDiagnosticModel
            {
                Severity = DocumentDiagnosticSeverity.Warning,
                Source = form.DisplayName,
                Category = "Export",
                Message = $"Form name will be exported as class '{sanitized}'.",
                Recommendation = "Use a C#-friendly form name to keep file and class names predictable."
            });
        }
    }

    private IEnumerable<ProjectOpenFormInteractionContext> EnumerateProjectOpenFormInteractions()
    {
        foreach (var form in CurrentProject.Forms)
        {
            var isActiveForm = string.Equals(form.Id, ActiveFormDocument?.Id, StringComparison.OrdinalIgnoreCase);
            var controls = isActiveForm
                ? Controls.Select(control => new ProjectControlReference(control.Id, control.Name, control.Type)).ToList()
                : form.Document.Controls.Select(control => new ProjectControlReference(control.Id, control.Name, control.Type)).ToList();
            var controlsByName = controls
                .Where(control => !string.IsNullOrWhiteSpace(control.Name))
                .GroupBy(control => control.Name, StringComparer.OrdinalIgnoreCase)
                .ToDictionary(group => group.Key, group => group.First(), StringComparer.OrdinalIgnoreCase);

            if (isActiveForm)
            {
                foreach (var interaction in Interactions.Where(IsOpenFormInteraction))
                    yield return CreateProjectOpenFormContext(
                        form,
                        interaction.SourceControlName,
                        interaction.TargetFormId,
                        interaction.TargetFormName,
                        controlsByName);

                continue;
            }

            foreach (var interaction in form.Document.Interactions.Where(IsOpenFormInteraction))
                yield return CreateProjectOpenFormContext(
                    form,
                    interaction.SourceControlName,
                    interaction.TargetFormId,
                    interaction.TargetFormName,
                    controlsByName);
        }
    }

    private static bool IsOpenFormInteraction(InteractionModel interaction)
    {
        return string.Equals(interaction.ActionType, InteractionModel.ActionOpenForm, StringComparison.OrdinalIgnoreCase);
    }

    private static bool IsOpenFormInteraction(InteractionFileModel interaction)
    {
        return string.Equals(interaction.ActionType, InteractionModel.ActionOpenForm, StringComparison.OrdinalIgnoreCase);
    }

    private static ProjectOpenFormInteractionContext CreateProjectOpenFormContext(
        DesignerFormDocument form,
        string sourceControlName,
        string targetFormId,
        string targetFormName,
        IReadOnlyDictionary<string, ProjectControlReference> controlsByName)
    {
        controlsByName.TryGetValue(sourceControlName ?? string.Empty, out var source);
        return new ProjectOpenFormInteractionContext(
            FormId: form.Id,
            FormDisplayName: form.DisplayName,
            SourceControlId: source?.Id ?? string.Empty,
            SourceControlName: source?.Name ?? sourceControlName ?? string.Empty,
            SourceDisplayName: string.IsNullOrWhiteSpace(source?.Name)
                ? string.IsNullOrWhiteSpace(sourceControlName) ? form.DisplayName : sourceControlName
                : $"{form.DisplayName}.{source.Name}",
            TargetFormId: targetFormId ?? string.Empty,
            TargetFormName: targetFormName ?? string.Empty);
    }

    private void AppendExportDiagnostics(ICollection<DocumentDiagnosticModel> diagnostics)
    {
        if (HasExportNamespaceError())
        {
            diagnostics.Add(new DocumentDiagnosticModel
            {
                Severity = DocumentDiagnosticSeverity.Error,
                Source = "Export",
                Category = "Namespace",
                Message = "Namespace проекта для экспорта пустой или некорректный.",
                Recommendation = "Укажите корректный namespace, например AvaloniaApplication1. Он должен состоять из C# identifiers, разделённых точками."
            });
        }

        var layoutPlan = BuildLayoutExportPlan();
        if (IsResponsiveLayoutExportMode)
        {
            diagnostics.Add(new DocumentDiagnosticModel
            {
                Severity = layoutPlan.FallbackToCanvas ? DocumentDiagnosticSeverity.Warning : DocumentDiagnosticSeverity.Info,
                Source = "Export",
                Category = "Layout",
                Message = layoutPlan.FallbackToCanvas
                    ? "Responsive layout недоступен для текущей формы, используется Canvas layout."
                    : "Responsive layout включён в экспериментальном режиме.",
                Recommendation = layoutPlan.Details
            });
        }

        if (ShouldExportRealDataGrid && Controls.Any(control => control.Type == DesignerControlTypes.DataGrid))
        {
            diagnostics.Add(new DocumentDiagnosticModel
            {
                Severity = DocumentDiagnosticSeverity.Warning,
                Source = "Export",
                Category = "DataGrid",
                Message = "Экспорт содержит настоящий Avalonia DataGrid.",
                Recommendation = "В новом Avalonia-проекте добавьте NuGet package Avalonia.Controls.DataGrid той же версии, что и Avalonia. XAML использует явный namespace assembly=Avalonia.Controls.DataGrid.",
            });
        }

        if (ShouldExportPortableDataGrid && Interactions.Any(interaction => IsDataGridSelectionChangedEvent(interaction.EventName)))
        {
            diagnostics.Add(new DocumentDiagnosticModel
            {
                Severity = DocumentDiagnosticSeverity.Warning,
                Source = "Export",
                Category = "Interactions",
                Message = "В portable export DataGrid экспортируется как безопасный визуальный placeholder.",
                Recommendation = "Для runtime-логики SelectionChanged включите режим 'Настоящий Avalonia DataGrid' и установите NuGet Avalonia.Controls.DataGrid. C# обработчик будет сгенерирован только для real DataGrid export."
            });
        }

        if (ShouldExportPortableDataGrid)
        {
            foreach (var grid in Controls.Where(control => control.Type == DesignerControlTypes.DataGrid))
            {
                var source = GetBindingSource(grid.BindingSourceId);
                string? message = null;
                string? recommendation = null;

                if (source is null)
                {
                    message = $"DataGrid '{grid.NameOrFallback()}' будет экспортирован как placeholder без источника данных.";
                    recommendation = "Подключите реальный BindingSource, если хотите получить таблицу с колонками.";
                }
                else if (source.Fields.Count == 0)
                {
                    message = $"DataGrid '{grid.NameOrFallback()}' будет экспортирован как placeholder: BindingSource не содержит полей.";
                    recommendation = "Добавьте поля в BindingSource или импортируйте схему из DLL/SQL.";
                }
                else if (!source.Fields.Any(field => field.IsVisible))
                {
                    message = $"DataGrid '{grid.NameOrFallback()}' будет экспортирован как placeholder: все поля BindingSource скрыты.";
                    recommendation = "Включите видимость хотя бы одной колонки перед экспортом.";
                }

                if (message is null)
                    continue;

                diagnostics.Add(new DocumentDiagnosticModel
                {
                    Severity = DocumentDiagnosticSeverity.Warning,
                    Source = "Export",
                    Category = "DataGrid",
                    Message = message,
                    Recommendation = recommendation ?? "",
                    RelatedControlId = grid.Id,
                    RelatedControlName = grid.Name
                });
            }
        }

        if (IsCleanUiGenerationMode)
        {
            foreach (var grid in Controls.Where(control => control.Type == DesignerControlTypes.DataGrid && !string.IsNullOrWhiteSpace(control.BindingSourceId)))
            {
                var source = GetBindingSource(grid.BindingSourceId);
                if (ShouldGenerateRuntimeBindingForSource(source))
                    continue;

                diagnostics.Add(new DocumentDiagnosticModel
                {
                    Severity = DocumentDiagnosticSeverity.Warning,
                    Source = grid.NameOrFallback(),
                    Category = "Export",
                    Message = $"DataGrid '{grid.NameOrFallback()}' использует BindingSource только как схему колонок.",
                    Recommendation = source is null
                        ? "Проверьте BindingSource. В чистом экспорте ItemsSource и demo data не генерируются."
                        : $"В чистом экспорте будут сгенерированы колонки из '{source.NameOrFallback()}', но ItemsSource нужно подключить в вашем runtime ViewModel вручную.",
                    RelatedControlId = grid.Id,
                    RelatedControlName = grid.Name
                });
            }
        }

        if (!IncludePluginRuntimeReferences)
        {
            foreach (var pluginControl in Controls.Where(IsPluginRuntimeControl))
            {
                diagnostics.Add(new DocumentDiagnosticModel
                {
                    Severity = DocumentDiagnosticSeverity.Warning,
                    Source = pluginControl.NameOrFallback(),
                    Category = "Export",
                    Message = $"Plugin control '{pluginControl.Type}' будет экспортирован безопасным placeholder-ом.",
                    Recommendation = "Включите 'Include plugin runtime references', если новый проект должен ссылаться на runtime-сборку плагина.",
                    RelatedControlId = pluginControl.Id,
                    RelatedControlName = pluginControl.Name
                });
            }
        }
    }

    [RelayCommand]
    private void NavigateToDiagnostic(DocumentDiagnosticModel? diagnostic)
    {
        if (diagnostic is null)
            return;

        var navigated = false;

        if (!string.IsNullOrWhiteSpace(diagnostic.RelatedBindingSourceId))
        {
            var source = GetBindingSource(diagnostic.RelatedBindingSourceId);
            if (source is not null)
            {
                SelectedBindingSource = source;
                navigated = true;
            }
        }

        if (!string.IsNullOrWhiteSpace(diagnostic.RelatedControlId))
        {
            var control = GetControl(diagnostic.RelatedControlId);
            if (control is not null)
            {
                SelectSingleControl(control);
                navigated = true;
            }
        }

        StatusText = navigated
            ? $"Открыта проблема: {diagnostic.Message}"
            : $"Проблема отмечена, но связанный объект уже недоступен: {diagnostic.Message}";
    }

