    private void SetLockStateForSelection(bool isLocked)
    {
        var targets = GetSelectedControls();
        if (targets.Count == 0)
            return;

        var changed = false;
        foreach (var control in targets)
        {
            if (control.IsLocked == isLocked)
                continue;

            control.IsLocked = isLocked;
            changed = true;
        }

        if (!changed)
            return;

        RaiseSelectionProperties();
        NotifyDesignerStateChanged();
        StatusText = isLocked
            ? $"Заблокировано элементов: {targets.Count(control => control.IsLocked)}."
            : "Выделенные элементы разблокированы.";
    }

    public double Snap(double value)
    {
        if (!IsGridSnapEnabled || SnapStep <= 1)
            return value;

        return Math.Round(value / SnapStep) * SnapStep;
    }

    public (double X, double Y) GetAbsolutePosition(DesignControlModel control)
    {
        var x = control.X;
        var y = control.Y;
        var currentParent = GetControl(control.ParentId);

        while (currentParent is not null)
        {
            x += currentParent.X;
            y += currentParent.Y;
            currentParent = GetControl(currentParent.ParentId);
        }

        return (x, y);
    }

    public DesignControlModel? FindDeepestContainerAt(double absoluteX, double absoluteY)
    {
        DesignControlModel? result = null;
        var maxDepth = -1;

        foreach (var control in Controls.Where(CanHostChildren).Where(control => !control.IsLocked))
        {
            var position = GetAbsolutePosition(control);
            var inside = absoluteX >= position.X
                && absoluteX <= position.X + control.Width
                && absoluteY >= position.Y
                && absoluteY <= position.Y + control.Height;

            if (!inside)
                continue;

            var depth = GetControlDepth(control);
            if (depth > maxDepth)
            {
                result = control;
                maxDepth = depth;
            }
        }

        return result;
    }

    public (double X, double Y) ToLocalPosition(string? parentId, double absoluteX, double absoluteY)
    {
        var parent = GetControl(parentId);
        if (parent is null)
            return (absoluteX, absoluteY);

        var parentPosition = GetAbsolutePosition(parent);
        return (absoluteX - parentPosition.X, absoluteY - parentPosition.Y);
    }

    public void ReparentControl(DesignControlModel control, string? newParentId, double absoluteX, double absoluteY)
    {
        var normalizedParentId = NormalizeId(newParentId);

        if (normalizedParentId == control.Id || IsDescendant(normalizedParentId, control.Id))
            return;

        control.ParentId = normalizedParentId;
        var parentLayoutMode = GetLayoutModeForParent(normalizedParentId);
        if (DesignerLayoutModes.IsAbsolute(parentLayoutMode))
        {
            var local = ToLocalPosition(normalizedParentId, absoluteX, absoluteY);
            control.X = Snap(local.X);
            control.Y = Snap(local.Y);
        }
        else if (DesignerLayoutModes.NormalizeMode(parentLayoutMode) == DesignerLayoutModes.Grid)
        {
            ApplyGridDropPlacement(control, normalizedParentId, absoluteX, absoluteY);
            control.X = 0;
            control.Y = 0;
        }
        else if (DesignerLayoutModes.NormalizeMode(parentLayoutMode) == DesignerLayoutModes.Stack)
        {
            ApplyStackDropOrder(control, normalizedParentId, absoluteX, absoluteY);
            control.X = 0;
            control.Y = 0;
        }
        else
        {
            control.X = 0;
            control.Y = 0;
        }

        ClampControlToSurface(control);
    }

    private void ApplyGridDropPlacement(DesignControlModel control, string? parentId, double absoluteX, double absoluteY)
    {
        var parent = GetControl(parentId);
        var columns = Math.Max(1, parent?.Columns ?? SurfaceLayoutColumns);
        var rows = Math.Max(1, parent?.Rows ?? SurfaceLayoutRows);
        var width = Math.Max(1, parent?.Width ?? PreviewFormWidth);
        var height = Math.Max(1, parent?.Height ?? PreviewFormHeight);
        var local = ToLocalPosition(parentId, absoluteX + (control.Width / 2), absoluteY + (control.Height / 2));
        control.GridColumn = Math.Clamp((int)Math.Floor(local.X / Math.Max(1, width / columns)), 0, columns - 1);
        control.GridRow = Math.Clamp((int)Math.Floor(local.Y / Math.Max(1, height / rows)), 0, rows - 1);
        control.GridColumnSpan = Math.Max(1, Math.Min(control.GridColumnSpan, columns - control.GridColumn));
        control.GridRowSpan = Math.Max(1, Math.Min(control.GridRowSpan, rows - control.GridRow));
    }

    private void ApplyStackDropOrder(DesignControlModel control, string? parentId, double absoluteX, double absoluteY)
    {
        var parent = GetControl(parentId);
        var orientation = DesignerLayoutModes.NormalizeOrientation(parent?.LayoutOrientation ?? SurfaceLayoutOrientation);
        var local = ToLocalPosition(parentId, absoluteX + (control.Width / 2), absoluteY + (control.Height / 2));
        var siblings = GetChildControls(parentId)
            .Where(sibling => sibling.Id != control.Id)
            .Select((sibling, index) => new { Sibling = sibling, Index = index })
            .OrderBy(item => Math.Max(0, item.Sibling.StackOrder))
            .ThenBy(item => item.Index)
            .Select(item => item.Sibling)
            .ToList();

        var insertion = siblings.Count;
        for (var index = 0; index < siblings.Count; index++)
        {
            var sibling = siblings[index];
            var midpoint = orientation == DesignerLayoutModes.Horizontal
                ? sibling.X + (sibling.Width / 2)
                : sibling.Y + (sibling.Height / 2);
            var probe = orientation == DesignerLayoutModes.Horizontal ? local.X : local.Y;
            if (probe < midpoint)
            {
                insertion = index;
                break;
            }
        }

        siblings.Insert(insertion, control);
        for (var index = 0; index < siblings.Count; index++)
            siblings[index].StackOrder = index;
    }

    public void ClampControlToSurface(DesignControlModel model)
    {
        var container = GetControl(model.ParentId);
        var containerWidth = container?.Width ?? PreviewFormWidth;
        var containerHeight = container?.Height ?? PreviewFormHeight;

        var maxWidth = Math.Max(40, containerWidth - Math.Max(0, model.X));
        var maxHeight = Math.Max(24, containerHeight - Math.Max(0, model.Y));

        if (model.Width > maxWidth)
            model.Width = maxWidth;

        if (model.Height > maxHeight)
            model.Height = maxHeight;

        if (IsAbsoluteLayoutParent(model.ParentId))
        {
            model.X = Math.Clamp(model.X, 0, Math.Max(0, containerWidth - model.Width));
            model.Y = Math.Clamp(model.Y, 0, Math.Max(0, containerHeight - model.Height));
        }
        else
        {
            model.X = 0;
            model.Y = 0;
        }
    }

    public void ClampAllControlsToSurface()
    {
        foreach (var control in Controls)
            ClampControlToSurface(control);
    }

    public void MoveSelectedControl(double dx, double dy)
    {
        var roots = GetEditableSelectedRootControls();
        if (roots.Count == 0)
            return;

        BeginUndoBatch();
        try
        {
            foreach (var control in roots)
            {
                if (!IsAbsoluteLayoutParent(control.ParentId))
                    continue;

                control.X += dx;
                control.Y += dy;
                ClampControlToSurface(control);
            }
        }
        finally
        {
            CommitUndoBatch();
        }
    }

    private void NudgeSelection(double dx, double dy)
    {
        MoveSelectedControl(dx, dy);
        StatusText = $"Nudged selection: {dx:0;-0;0}, {dy:0;-0;0}px";
    }

