    public DesignControlModel? TryCreateControlFromToolboxDrop(
        string type,
        double x,
        double y,
        string? parentId,
        bool bypassGridSnap,
        string targetDocumentId)
    {
        if (!IsActiveDocumentTarget(targetDocumentId, out var activeDocumentId))
        {
            TraceDocumentDebug(
                "DropRejected",
                $"type={type}; targetDocument={targetDocumentId}; activeDocument={activeDocumentId}; x={x:0.##}; y={y:0.##}",
                toOutput: true,
                warning: true);
            StatusText = "Drop отменён: активная форма уже изменилась.";
            return null;
        }

        return CreateControlCore(type, x, y, parentId, bypassGridSnap, activeDocumentId, "ToolboxDrop");
    }

    public DesignControlModel CreateControl(string type, double x, double y, string? parentId = null, bool bypassGridSnap = false)
    {
        return CreateControlCore(type, x, y, parentId, bypassGridSnap, ActiveDocumentId, "CreateControl");
    }

    private DesignControlModel CreateControlCore(string type, double x, double y, string? parentId, bool bypassGridSnap, string documentId, string reason)
    {
        // Контрол всегда создается из стартового шаблона,
        // а координаты сразу привязываются к сетке и границам контейнера.
        var model = CreateDefaultControl(type);
        model.Name = GetUniqueControlName(type);
        model.ParentId = NormalizeId(parentId);
        var parentLayoutMode = GetLayoutModeForParent(model.ParentId);

        if (DesignerLayoutModes.IsAbsolute(parentLayoutMode))
        {
            var local = ToLocalPosition(model.ParentId, x, y);
            model.X = bypassGridSnap ? local.X : Snap(local.X);
            model.Y = bypassGridSnap ? local.Y : Snap(local.Y);
        }
        else if (DesignerLayoutModes.NormalizeMode(parentLayoutMode) == DesignerLayoutModes.Grid)
        {
            ApplyGridDropPlacement(model, model.ParentId, x, y);
            model.X = 0;
            model.Y = 0;
        }
        else if (DesignerLayoutModes.NormalizeMode(parentLayoutMode) == DesignerLayoutModes.Stack)
        {
            ApplyStackDropOrder(model, model.ParentId, x, y);
            model.X = 0;
            model.Y = 0;
        }
        else
        {
            model.X = 0;
            model.Y = 0;
        }

        ClampControlToSurface(model);
        TrackControlDocument(model, documentId);
        Controls.Add(model);
        SelectedControl = model;
        TraceDocumentDebug(reason, $"created={model.Name}/{model.Id}; type={type}; doc={documentId}; x={model.X:0.##}; y={model.Y:0.##}", toOutput: false);
        return model;
    }

    private bool IsActiveDocumentTarget(string? targetDocumentId, out string activeDocumentId)
    {
        activeDocumentId = ActiveDocumentId;
        if (string.IsNullOrWhiteSpace(targetDocumentId))
            return !string.IsNullOrWhiteSpace(activeDocumentId);

        return string.Equals(targetDocumentId, activeDocumentId, StringComparison.OrdinalIgnoreCase);
    }

    private void TrackControlDocument(DesignControlModel? control, string? documentId)
    {
        if (control is null || string.IsNullOrWhiteSpace(control.Id) || string.IsNullOrWhiteSpace(documentId))
            return;

        _controlDocumentIdsByControlId[control.Id] = documentId;
    }

    private string GetTrackedControlDocumentId(DesignControlModel? control)
    {
        if (control is null || string.IsNullOrWhiteSpace(control.Id))
            return "";

        return _controlDocumentIdsByControlId.TryGetValue(control.Id, out var documentId)
            ? documentId
            : "";
    }

    public void MarkCanvasRenderedDocument(string reason, int wrapperCount = -1, int previewRowsCount = -1)
    {
        if (wrapperCount >= 0 || previewRowsCount >= 0)
        {
            _lastCanvasWrapperCount = Math.Max(0, wrapperCount);
            _lastPreviewRowsCount = Math.Max(0, previewRowsCount);
        }

        TrackRefreshOperation("RenderCanvas", reason);
        _canvasRenderedDocumentId = ActiveDocumentId;
        OnPropertyChanged(nameof(CanvasRenderedDocumentId));
        TraceDocumentDebug("RenderCanvas", $"reason={reason}; controls={Controls.Count}; wrappers={_lastCanvasWrapperCount}; previewRows={_lastPreviewRowsCount}", toOutput: false);
    }

    public void TraceDocumentDebug(string eventName, string details = "", bool toOutput = false, bool warning = false)
    {
        var selectedDocumentId = GetTrackedControlDocumentId(SelectedControl);
        var message =
            $"[DocumentIsolation] {eventName}: active={ActiveDocumentName}/{ActiveDocumentId}; " +
            $"openedTab={SelectedDocumentTab?.DocumentId ?? "-"}; " +
            $"selected={SelectedControl?.Name ?? "-"}:{SelectedControl?.Id ?? "-"} doc={selectedDocumentId}; " +
            $"inspector={_propertyGridContextDocumentId}/{_propertyGridContextControlId}; canvas={_canvasRenderedDocumentId}; {details}";

        Debug.WriteLine(message);
        AddInteractionTrace(eventName, $"{details}; openedTab={SelectedDocumentTab?.DocumentId ?? "-"}; inspector={_propertyGridContextDocumentId}/{_propertyGridContextControlId}; canvas={_canvasRenderedDocumentId}");

        if (!toOutput)
            return;

        LogWorkspace(
            warning ? WorkspaceLogLevel.Warning : WorkspaceLogLevel.Info,
            OutputCategoryDiagnostics,
            message);
    }

    public void TraceDocumentStateSnapshot(string reason, bool toOutput = false)
    {
        var selectedDocumentId = GetTrackedControlDocumentId(SelectedControl);
        var rowContexts = PropertyGridCategories
            .SelectMany(category => category.Rows)
            .Select(row => $"{row.ContextDocumentId}/{row.ContextControlId}/{row.Key}")
            .Take(12);
        var forms = CurrentProject.Forms
            .Select(form => $"{form.DisplayName}:{form.Id}:{form.Document?.Controls.Count ?? 0}")
            .Take(8);
        var message =
            $"[DocumentStateDump] {reason}: active={ActiveDocumentName}/{ActiveDocumentId}; " +
            $"selected={SelectedControl?.Name ?? "-"}:{SelectedControl?.Id ?? "-"} selectedDoc={selectedDocumentId}; " +
            $"tabs={DocumentTabs.Count}; selectedTab={SelectedDocumentTab?.DocumentId ?? "-"}; " +
            $"projectItem={SelectedProjectExplorerItem?.DisplayName ?? "-"}:{SelectedProjectExplorerItem?.TargetId ?? "-"}; " +
            $"session={DocumentSessionId}; mode={WorkspaceMode}; busy={IsBusy}; preview={IsUserPreviewMode}; " +
            $"controls={Controls.Count}; bindings={BindingSources.Count}; interactions={Interactions.Count}; " +
            $"propertyRows={PropertyGridCategories.Sum(category => category.Rows.Count)}; " +
            $"inspectorContext={PropertyGridContextDocumentId}/{PropertyGridContextControlId}; " +
            $"rowContexts=[{string.Join(", ", rowContexts)}]; " +
            $"flags=applyingDocument:{_isApplyingDocument}, selection:{_isUpdatingSelectionState}, structure:{_isUpdatingStructureSelection}, " +
            $"projectExplorer:{_isUpdatingProjectExplorerSelection}, rebuildingGrid:{_isRebuildingPropertyGrid}, liveGrid:{_isPropertyGridLiveGesture}, " +
            $"historySuspended:{_isHistorySuspended}, undoBatch:{_undoBatchDepth}; " +
            $"forms=[{string.Join(", ", forms)}]; subscriptions={_controlPropertySubscriptions.Count}";

        Debug.WriteLine(message);
        if (toOutput)
            LogWorkspace(WorkspaceLogLevel.Info, OutputCategoryDiagnostics, message);
    }

    public void DumpEditorState(string reason = "Manual")
    {
        TraceDocumentStateSnapshot(reason, toOutput: true);
        DumpInteractionState(reason);
    }

    public void DumpInteractionState(string reason = "Manual", string viewState = "")
    {
        var selectedDocumentId = GetTrackedControlDocumentId(SelectedControl);
        var rowContexts = PropertyGridCategories
            .SelectMany(category => category.Rows)
            .Select(row => $"{row.ContextDocumentId}/{row.ContextControlId}/{row.Key}:{row.Editor}")
            .Take(16);
        var selectedRows = SelectedControlIds.Take(8);
        var message =
            $"[InteractionState] reason={reason}; active={ActiveDocumentName}/{ActiveDocumentId}; " +
            $"session={DocumentSessionId}; canvas={CanvasRenderedDocumentId}; openedTab={SelectedDocumentTab?.DocumentId ?? "-"}; " +
            $"selected={SelectedControl?.Name ?? "-"}:{SelectedControl?.Id ?? "-"} selectedDoc={selectedDocumentId}; selectedIds=[{string.Join(",", selectedRows)}]; " +
            $"inspector={PropertyGridContextDocumentId}/{PropertyGridContextControlId}; rows={PropertyGridCategories.Sum(category => category.Rows.Count)}; rowContexts=[{string.Join(", ", rowContexts)}]; " +
            $"mode={WorkspaceMode}; preview={IsUserPreviewMode}; busy={IsBusy}; " +
            $"flags=propertyEditor:{IsPropertyEditorFocused}, editingGrid:{_isEditingPropertyGrid}, applyingDocument:{_isApplyingDocument}, switchingForm:{_isSwitchingActiveForm}, " +
            $"inspectorInteraction:{_isInspectorInteractionActive}:{_inspectorInteractionKind}:depth={_inspectorInteractionDepth}, pendingInspectorRebuild:{_pendingInspectorRebuild}:{_pendingInspectorRebuildReason}, " +
            $"rebuildingGrid:{_isRebuildingPropertyGrid}, liveGrid:{_isPropertyGridLiveGesture}, pendingLiveGrid:{_hasPendingPropertyGridLiveRefresh}, " +
            $"deferredGrid:{_hasDeferredPropertyGridRebuild}:{_deferredPropertyGridRebuildReason}, " +
            $"selectionUpdate:{_isUpdatingSelectionState}, structureUpdate:{_isUpdatingStructureSelection}, projectExplorerUpdate:{_isUpdatingProjectExplorerSelection}, " +
            $"structureSuspended:{_isStructureTreeRefreshSuspended}, diagnosticsScheduled:{_isDiagnosticsRefreshScheduled}, exportScheduled:{_isExportChecklistRefreshScheduled}, " +
            $"undoBatch:{_undoBatchDepth}, historySuspended:{_isHistorySuspended}; " +
            $"editingRow={_editingPropertyGridDocumentId}/{_editingPropertyGridControlId}/{_editingPropertyGridKey}; selectedInteraction={SelectedInteraction?.SourceControlName ?? "-"}:{SelectedInteraction?.ActionType ?? "-"}; " +
            $"{viewState}";

        Debug.WriteLine(message);
        AddInteractionTrace("DumpInteractionState", $"reason={reason}; {viewState}");
        LogWorkspace(WorkspaceLogLevel.Info, OutputCategoryDiagnostics, message);
    }

    public void BeginInspectorInteraction(string reason, bool logToOutput = true, bool dumpState = true)
    {
        _inspectorInteractionDepth++;
        if (_isInspectorInteractionActive)
        {
            TraceDocumentDebug(
                "INSPECTOR_INTERACTION_NESTED_START",
                $"reason={reason}; depth={_inspectorInteractionDepth}; activeKind={_inspectorInteractionKind}",
                toOutput: false);
            return;
        }

        _isInspectorInteractionActive = true;
        _inspectorInteractionKind = reason;
        TraceDocumentDebug(
            "INSPECTOR_INTERACTION_START",
            $"reason={reason}; active={ActiveDocumentId}; selected={SelectedControl?.Name ?? "-"}:{SelectedControl?.Id ?? "-"}",
            toOutput: logToOutput);
        OnPropertyChanged(nameof(IsInspectorInteractionActive));
        if (dumpState)
            DumpInteractionState($"INSPECTOR_INTERACTION_START:{reason}");
    }

    public void EndInspectorInteraction(string reason, bool logToOutput = true, bool dumpState = true)
    {
        if (_inspectorInteractionDepth > 0)
            _inspectorInteractionDepth--;

        if (_inspectorInteractionDepth > 0)
        {
            TraceDocumentDebug(
                "INSPECTOR_INTERACTION_NESTED_END",
                $"reason={reason}; depth={_inspectorInteractionDepth}; activeKind={_inspectorInteractionKind}",
                toOutput: false);
            return;
        }

        if (!_isInspectorInteractionActive)
            return;

        var endedKind = _inspectorInteractionKind;
        _isInspectorInteractionActive = false;
        _inspectorInteractionDepth = 0;
        _inspectorInteractionKind = "";
        TraceDocumentDebug(
            "INSPECTOR_INTERACTION_END",
            $"reason={reason}; endedKind={endedKind}; pendingRebuild={_pendingInspectorRebuild}:{_pendingInspectorRebuildReason}",
            toOutput: logToOutput);
        OnPropertyChanged(nameof(IsInspectorInteractionActive));
        if (dumpState)
            DumpInteractionState($"INSPECTOR_INTERACTION_END:{reason}");

        if (!_pendingInspectorRebuild)
            return;

        var rebuildReason = string.IsNullOrWhiteSpace(_pendingInspectorRebuildReason)
            ? $"DeferredInspectorInteraction:{endedKind}"
            : _pendingInspectorRebuildReason;
        SchedulePendingInspectorRebuild(rebuildReason);
    }

    private void SchedulePendingInspectorRebuild(string reason)
    {
        _pendingInspectorRebuild = true;
        _pendingInspectorRebuildReason = string.IsNullOrWhiteSpace(_pendingInspectorRebuildReason)
            ? reason
            : _pendingInspectorRebuildReason;

        if (_isPendingInspectorRebuildScheduled)
            return;

        _isPendingInspectorRebuildScheduled = true;
        Dispatcher.UIThread.Post(
            () =>
            {
                _isPendingInspectorRebuildScheduled = false;

                if (!_pendingInspectorRebuild)
                    return;

                if (_isInspectorInteractionActive)
                {
                    TraceDocumentDebug(
                        "PROPERTYGRID_REBUILD_DEFERRED_STILL_INTERACTING",
                        $"reason={_pendingInspectorRebuildReason}; activeInteraction={_inspectorInteractionKind}",
                        toOutput: false,
                        warning: true);
                    SchedulePendingInspectorRebuild(_pendingInspectorRebuildReason);
                    return;
                }

                var pendingReason = string.IsNullOrWhiteSpace(_pendingInspectorRebuildReason)
                    ? reason
                    : _pendingInspectorRebuildReason;
                _pendingInspectorRebuild = false;
                _pendingInspectorRebuildReason = "";
                RebuildPropertyGrid(pendingReason);
            },
            DispatcherPriority.Background);
    }

    private bool DeferInspectorRebuildIfNeeded(string operation, string reason)
    {
        if (!_isInspectorInteractionActive)
            return false;

        _pendingInspectorRebuild = true;
        var request = $"{operation}:{reason}";
        _pendingInspectorRebuildReason = string.IsNullOrWhiteSpace(_pendingInspectorRebuildReason)
            ? request
            : $"{_pendingInspectorRebuildReason}; {request}";

        var stack = TrimStackTrace(new StackTrace(skipFrames: 2, fNeedFileInfo: false).ToString());
        var message =
            $"PROPERTYGRID_REBUILD_DURING_INTERACTION operation={operation}; reason={reason}; " +
            $"callStack={stack}; activeDocument={ActiveDocumentId}; openedTab={SelectedDocumentTab?.DocumentId ?? "-"}; " +
            $"selectedControl={SelectedControl?.Name ?? "-"}:{SelectedControl?.Id ?? "-"}; " +
            $"inspector={PropertyGridContextDocumentId}/{PropertyGridContextControlId}; " +
            $"isTextEditorFocused={IsPropertyEditorFocused}; isInspectorInteractionActive={_isInspectorInteractionActive}; " +
            $"interactionKind={_inspectorInteractionKind}; isComboDropDownOpen={_inspectorInteractionKind.Contains("Combo", StringComparison.OrdinalIgnoreCase)}; " +
            $"isColorPickerOpen={_inspectorInteractionKind.Contains("Color", StringComparison.OrdinalIgnoreCase)}; " +
            $"isLogicEditing={_inspectorInteractionKind.Contains("Logic", StringComparison.OrdinalIgnoreCase)}; " +
            $"isDragging={_inspectorInteractionKind.Contains("Drag", StringComparison.OrdinalIgnoreCase) || _isPropertyGridLiveGesture}; " +
            $"isRefreshingPropertyGrid={_isRebuildingPropertyGrid}; pendingReason={_pendingInspectorRebuildReason}";

        Debug.WriteLine(message);
        TraceDocumentDebug(
            "PROPERTYGRID_REBUILD_DEFERRED",
            $"operation={operation}; reason={reason}; pending={_pendingInspectorRebuildReason}",
            toOutput: false,
            warning: true);
        return true;
    }

    public void ResetInteractionStateFromShell(string reason = "ManualReset")
    {
        DumpInteractionState($"BeforeResetInteractionState:{reason}");

        if (_isEditingPropertyGrid)
            EndPropertyGridTextEdit();

        _isEditingPropertyGrid = false;
        _isPropertyGridEditUndoBatchOpen = false;
        _hasDeferredPropertyGridRebuild = false;
        _deferredPropertyGridRebuildReason = "";
        _editingPropertyGridDocumentId = "";
        _editingPropertyGridControlId = "";
        _editingPropertyGridKey = "";
        _editingPropertyGridText = "";
        _isPropertyGridLiveGesture = false;
        _hasPendingPropertyGridLiveRefresh = false;
        _propertyGridLiveGestureSessionId = "";
        _propertyGridLiveRefreshTimer.Stop();
        _isInspectorInteractionActive = false;
        _inspectorInteractionDepth = 0;
        _pendingInspectorRebuild = false;
        _isPendingInspectorRebuildScheduled = false;
        _pendingInspectorRebuildReason = "";
        _inspectorInteractionKind = "";

        _isUpdatingSelectionState = false;
        _isUpdatingStructureSelection = false;
        _isUpdatingProjectExplorerSelection = false;
        _isStructureTreeRefreshSuspended = false;
        _isRebuildingPropertyGrid = false;
        _isSwitchingActiveForm = false;

        SelectedInteraction = null;
        SelectedBindingSource = null;
        SelectedLayoutGridRow = null;
        SelectedLayoutGridColumn = null;
        ClearSelection();

        RebuildPropertyGrid($"ResetInteractionState:{reason}");
        RebuildStructureTree();
        RaiseBindingEditorProperties();
        RaiseInteractionDesignerProperties();
        RaiseInteractionLookupProperties();
        RaiseActiveLayoutProperties();
        NotifyDesignerStateChanged(trackHistory: false);
        OnPropertyChanged(nameof(IsPropertyEditorFocused));
        OnPropertyChanged(nameof(IsInspectorInteractionActive));

        StatusText = "Interaction state reset.";
        DumpInteractionState($"AfterResetInteractionState:{reason}");
    }

    public void BeginPropertyGridTextEdit(PropertyGridRowViewModel row, string text)
    {
        if (_isEditingPropertyGrid && !IsEditingPropertyGridRow(row))
            EndPropertyGridTextEdit();

        TracePropertyGridEdit(
            "PROPERTY_EDIT_BEGIN",
            row,
            $"property={row.Key}; editor={row.Editor}; text={text ?? ""}");

        if (!CanApplyPropertyGridRow(row, text ?? string.Empty))
            return;

        BeginInspectorInteraction(
            $"PropertyTextEdit:{row.ContextDocumentId}/{row.ContextControlId}/{row.Key}",
            logToOutput: false,
            dumpState: false);

        if (!_isEditingPropertyGrid && !_isPropertyGridEditUndoBatchOpen)
        {
            BeginUndoBatch();
            _isPropertyGridEditUndoBatchOpen = true;
        }

        _isEditingPropertyGrid = true;
        _editingPropertyGridDocumentId = row.ContextDocumentId;
        _editingPropertyGridControlId = row.ContextControlId;
        _editingPropertyGridKey = row.Key;
        _editingPropertyGridText = text ?? string.Empty;
        OnPropertyChanged(nameof(IsPropertyEditorFocused));
        TracePropertyGridEdit(
            "PG_EDIT_BEGIN",
            row,
            $"text={_editingPropertyGridText}; model={GetPropertyGridTargetValue(row)}");
    }

    public void UpdatePropertyGridTextEdit(PropertyGridRowViewModel row, string text)
    {
        if (!IsEditingPropertyGridRow(row))
            BeginPropertyGridTextEdit(row, text);

        var previous = row.Value;
        _editingPropertyGridText = text ?? string.Empty;
        TracePropertyGridEdit(
            "PG_UI_TEXT_CHANGED",
            row,
            $"rowValueBefore={previous}; textBoxText={_editingPropertyGridText}; isApplyingDocument={_isApplyingDocument}; isRefreshingPropertyGrid={_isRebuildingPropertyGrid}");
    }

    public void CommitPropertyGridTextEdit(PropertyGridRowViewModel row, string text)
    {
        if (!IsEditingPropertyGridRow(row))
            BeginPropertyGridTextEdit(row, text);

        try
        {
            CommitPropertyGridEdit(row, text);
        }
        catch (Exception ex)
        {
            TracePropertyGridEdit(
                "PG_APPLY_EXCEPTION",
                row,
                $"property={row.Key}; exception={ex.GetType().Name}; message={ex.Message}");
            throw;
        }
        finally
        {
            EndPropertyGridTextEdit(row);
        }
    }

    public void CommitPropertyGridEdit(PropertyGridRowViewModel? row, string value)
    {
        if (row is null)
        {
            DumpInteractionState("AfterPropertyEditRejected:row-null");
            TraceDocumentDebug(
                "EDIT_REJECTED",
                $"reason=row-null; activeDocument={ActiveDocumentId}; selected={SelectedControl?.Name ?? "-"}:{SelectedControl?.Id ?? "-"}; attempted={value ?? ""}",
                toOutput: true,
                warning: true);
            return;
        }

        TracePropertyGridEdit(
            "EDIT_ATTEMPT",
            row,
            $"property={row.Key}; editor={row.Editor}; attempted={value ?? ""}; isReadOnly={row.IsReadOnly}; active={ActiveDocumentId}; selected={SelectedControl?.Name ?? "-"}:{SelectedControl?.Id ?? "-"}");

        if (row.IsReadOnly)
        {
            TracePropertyGridEdit(
                "EDIT_REJECTED",
                row,
                $"reason=readonly; property={row.Key}; attempted={value ?? ""}");
            DumpInteractionState($"AfterPropertyEditRejected:readonly:{row.Key}");
            return;
        }

        var newValue = value ?? string.Empty;
        if (!CanApplyPropertyGridRow(row, newValue))
        {
            DumpInteractionState($"AfterPropertyEditRejected:CanApply:{row.Key}");
            return;
        }

        TracePropertyGridEdit(
            "EDIT_ACCEPTED",
            row,
            $"property={row.Key}; newValue={newValue}");

        var ownsUndoBatch = !_isPropertyGridEditUndoBatchOpen;
        if (ownsUndoBatch)
            BeginUndoBatch();

        try
        {
            var oldModelValue = GetPropertyGridTargetValue(row);
            TracePropertyGridEdit(
                "PG_DIRECT_COMMIT_START",
                row,
                $"property={row.Key}; oldModelValue={oldModelValue}; newValue={newValue}");

            row.Value = newValue;
            row.CommitValue();

            if (row.HasValidationError)
            {
                if (row.Editor == PropertyGridEditorKind.Number)
                {
                    TracePropertyGridEdit(
                        "NUMERIC_PROPERTY_VALIDATION_FAILED",
                        row,
                        $"property={row.Key}; input={newValue}; reason={row.ValidationMessage}");
                }

                TracePropertyGridEdit(
                    "PROPERTY_EDIT_COMMIT",
                    row,
                    $"property={row.Key}; oldValue={oldModelValue}; newValue={newValue}; success=False; validation={row.ValidationMessage}");
                return;
            }

            if (string.Equals(row.Key, nameof(DesignControlModel.Text), StringComparison.OrdinalIgnoreCase)
                && string.IsNullOrEmpty(newValue))
            {
                TracePropertyGridEdit(
                    "TEXT_PROPERTY_EMPTY_VALUE_APPLIED",
                    row,
                    $"target={row.ContextControlName}:{row.ContextControlId}; property={row.Key}; oldValue={oldModelValue}; newValue=<empty>");
                TracePropertyGridEdit(
                    "TEXT_PROPERTY_DEFAULT_FALLBACK_SUPPRESSED",
                    row,
                    "reason=user explicitly set empty value");
            }

            TracePropertyGridEdit(
                "PG_DIRECT_COMMIT_END",
                row,
                $"property={row.Key}; modelValue={GetPropertyGridTargetValue(row)}; validation={row.ValidationMessage}");
            TracePropertyGridEdit(
                "PROPERTY_EDIT_COMMIT",
                row,
                $"property={row.Key}; oldValue={oldModelValue}; newValue={newValue}; success=True");
        }
        catch (Exception ex)
        {
            row.ValidationMessage = ex.Message;
            TracePropertyGridEdit(
                "PG_DIRECT_COMMIT_EXCEPTION",
                row,
                $"property={row.Key}; exception={ex.GetType().Name}; message={ex.Message}");
            TracePropertyGridEdit(
                "PROPERTY_EDIT_COMMIT",
                row,
                $"property={row.Key}; newValue={newValue}; success=False; exception={ex.GetType().Name}; message={ex.Message}");
        }
        finally
        {
            if (ownsUndoBatch)
                CommitUndoBatch();
        }
    }

    public void EndPropertyGridTextEdit(PropertyGridRowViewModel? row = null)
    {
        if (row is not null && !IsEditingPropertyGridRow(row))
        {
            TracePropertyGridEdit(
                "PROPERTY_EDIT_STATE_STUCK",
                row,
                $"reason=end-row-mismatch; activeEditor={_editingPropertyGridDocumentId}/{_editingPropertyGridControlId}/{_editingPropertyGridKey}; forcingCleanup=True");
            row = null;
        }

        var shouldCommitBatch = _isPropertyGridEditUndoBatchOpen;
        var shouldRunDeferredRebuild = _hasDeferredPropertyGridRebuild;
        var deferredRebuildReason = string.IsNullOrWhiteSpace(_deferredPropertyGridRebuildReason)
            ? "DeferredAfterPropertyEditor"
            : _deferredPropertyGridRebuildReason;
        _isEditingPropertyGrid = false;
        _isPropertyGridEditUndoBatchOpen = false;
        _hasDeferredPropertyGridRebuild = false;
        _deferredPropertyGridRebuildReason = "";
        _editingPropertyGridDocumentId = "";
        _editingPropertyGridControlId = "";
        _editingPropertyGridKey = "";
        _editingPropertyGridText = "";
        OnPropertyChanged(nameof(IsPropertyEditorFocused));

        if (shouldCommitBatch)
            CommitUndoBatch();

        if (shouldRunDeferredRebuild)
        {
            _pendingInspectorRebuild = true;
            _pendingInspectorRebuildReason = string.IsNullOrWhiteSpace(_pendingInspectorRebuildReason)
                ? deferredRebuildReason
                : $"{_pendingInspectorRebuildReason}; {deferredRebuildReason}";
        }

        EndInspectorInteraction(row is null
            ? "PropertyTextEdit"
            : $"PropertyTextEdit:{row.ContextDocumentId}/{row.ContextControlId}/{row.Key}",
            logToOutput: false,
            dumpState: false);
    }

    public void CancelPropertyGridTextEdit(PropertyGridRowViewModel? row = null)
    {
        if (row is not null && !IsEditingPropertyGridRow(row))
        {
            TracePropertyGridEdit(
                "PROPERTY_EDIT_STATE_STUCK",
                row,
                $"reason=cancel-row-mismatch; activeEditor={_editingPropertyGridDocumentId}/{_editingPropertyGridControlId}/{_editingPropertyGridKey}; forcingCleanup=True");
            row = null;
        }

        if (row is not null)
        {
            TracePropertyGridEdit(
                "PROPERTY_EDIT_CANCEL",
                row,
                $"property={row.Key}; editor={row.Editor}");
        }

        _isEditingPropertyGrid = false;
        if (_isPropertyGridEditUndoBatchOpen && _undoBatchDepth > 0)
        {
            _undoBatchDepth--;
            if (_undoBatchDepth == 0)
                _undoBatchTrackHistory = false;
        }

        _isPropertyGridEditUndoBatchOpen = false;
        _hasDeferredPropertyGridRebuild = false;
        _deferredPropertyGridRebuildReason = "";
        _editingPropertyGridDocumentId = "";
        _editingPropertyGridControlId = "";
        _editingPropertyGridKey = "";
        _editingPropertyGridText = "";
        OnPropertyChanged(nameof(IsPropertyEditorFocused));
        EndInspectorInteraction(row is null
            ? "PropertyTextEditCancel"
            : $"PropertyTextEditCancel:{row.ContextDocumentId}/{row.ContextControlId}/{row.Key}",
            logToOutput: false,
            dumpState: false);
    }

    private bool IsEditingPropertyGridRow(PropertyGridRowViewModel row)
    {
        return _isEditingPropertyGrid
            && string.Equals(row.ContextDocumentId, _editingPropertyGridDocumentId, StringComparison.OrdinalIgnoreCase)
            && string.Equals(row.ContextControlId, _editingPropertyGridControlId, StringComparison.OrdinalIgnoreCase)
            && string.Equals(row.Key, _editingPropertyGridKey, StringComparison.OrdinalIgnoreCase);
    }

    private void PropertyGridRow_ValueTrace(PropertyGridRowViewModel row, string oldValue, string newValue, string stack)
    {
        var isCurrentEdit = IsEditingPropertyGridRow(row);
        var isOverwrite = isCurrentEdit && !string.Equals(newValue, _editingPropertyGridText, StringComparison.Ordinal);
        var message =
            $"[PropertyGridTrace] PG_ROW_VALUE_SET: property={row.Key}; oldRowValue={oldValue}; newRowValue={newValue}; " +
            $"editing={isCurrentEdit}; expectedText={_editingPropertyGridText}; rowDocument={row.ContextDocumentId}; rowControl={row.ContextControlName}:{row.ContextControlId}; " +
            $"activeDocument={ActiveDocumentId}; selected={SelectedControl?.Name ?? "-"}:{SelectedControl?.Id ?? "-"}; " +
            $"caller={TrimStackTrace(stack)}";

        Debug.WriteLine(message);
        if (isOverwrite)
            LogWorkspace(WorkspaceLogLevel.Warning, OutputCategoryDiagnostics, message);
    }

    private void TracePropertyGridEdit(string eventName, PropertyGridRowViewModel row, string details)
    {
        var message =
            $"[PropertyGridTrace] {eventName}: rowKey={row.Key}; activeDocument={ActiveDocumentId}; " +
            $"selectedControl={SelectedControl?.Name ?? "-"}:{SelectedControl?.Id ?? "-"}; " +
            $"rowDocument={row.ContextDocumentId}; rowControl={row.ContextControlName}:{row.ContextControlId}; " +
            $"isApplyingDocument={_isApplyingDocument}; isRefreshingPropertyGrid={_isRebuildingPropertyGrid}; {details}";
        Debug.WriteLine(message);

        if (eventName.Contains("EXCEPTION", StringComparison.OrdinalIgnoreCase)
            || eventName.Contains("REJECT", StringComparison.OrdinalIgnoreCase)
            || eventName.Contains("MISSING", StringComparison.OrdinalIgnoreCase))
        {
            var level = eventName.Contains("REJECT", StringComparison.OrdinalIgnoreCase)
                || eventName.Contains("EXCEPTION", StringComparison.OrdinalIgnoreCase)
                ? WorkspaceLogLevel.Warning
                : WorkspaceLogLevel.Info;
            LogWorkspace(level, OutputCategoryDiagnostics, message);
        }
    }

    private string GetPropertyGridTargetValue(PropertyGridRowViewModel row)
    {
        if (!string.IsNullOrWhiteSpace(row.ContextControlId))
        {
            var control = Controls.FirstOrDefault(item => string.Equals(item.Id, row.ContextControlId, StringComparison.OrdinalIgnoreCase));
            if (control is null)
            {
                TraceDocumentDebug(
                    "PG_TARGET_VALUE_MISSING_CONTROL",
                    $"rowDocument={row.ContextDocumentId}; rowControl={row.ContextControlName}:{row.ContextControlId}; key={row.Key}",
                    toOutput: true,
                    warning: true);
                return "";
            }

            var property = typeof(DesignControlModel).GetProperty(row.Key, BindingFlags.Instance | BindingFlags.Public);
            if (property is null)
            {
                TraceDocumentDebug(
                    "PG_TARGET_VALUE_MISSING_PROPERTY",
                    $"rowDocument={row.ContextDocumentId}; rowControl={row.ContextControlName}:{row.ContextControlId}; key={row.Key}",
                    toOutput: true,
                    warning: true);
                return "";
            }

            return property.GetValue(control)?.ToString() ?? "";
        }

        return row.Key switch
        {
            "FormTitle" => FormTitle,
            nameof(DesignWidth) => DesignWidth.ToString(CultureInfo.InvariantCulture),
            nameof(DesignHeight) => DesignHeight.ToString(CultureInfo.InvariantCulture),
            nameof(SurfaceBackground) => SurfaceBackground,
            nameof(FormWindowState) => FormWindowState,
            nameof(FormStartupLocation) => FormStartupLocation,
            nameof(SurfaceLayoutMode) => SurfaceLayoutMode,
            nameof(SurfaceLayoutOrientation) => SurfaceLayoutOrientation,
            nameof(SurfaceLayoutSpacing) => SurfaceLayoutSpacing.ToString(CultureInfo.InvariantCulture),
            nameof(SurfaceLayoutColumns) => SurfaceLayoutColumns.ToString(CultureInfo.InvariantCulture),
            nameof(SurfaceLayoutRows) => SurfaceLayoutRows.ToString(CultureInfo.InvariantCulture),
            nameof(SurfaceGridColumnDefinitions) => SurfaceGridColumnDefinitions,
            nameof(SurfaceGridRowDefinitions) => SurfaceGridRowDefinitions,
            _ => ""
        };
    }

    private static string TrimStackTrace(string stack)
    {
        if (string.IsNullOrWhiteSpace(stack))
            return "";

        return string.Join(" <- ", stack
            .Split(new[] { Environment.NewLine }, StringSplitOptions.RemoveEmptyEntries)
            .Select(line => line.Trim())
            .Take(5));
    }

    public BindingSourceModel AddBindingSource()
    {
        var name = GetUniqueBindingSourceName("BindingSource");

        var bindingSource = new BindingSourceModel
        {
            Name = name,
            Path = name,
            ItemTypeName = "RowItem",
            Description = "Ручной источник данных. Добавьте поля или импортируйте схему из DLL/SQL.",
            SourceKind = "Manual",
            SourceSchemaName = "dbo"
        };

        BindingSources.Add(bindingSource);
        SelectedBindingSource = bindingSource;
        return bindingSource;
    }

    public BindingSourceModel AddSqlBindingSource()
    {
        var source = AddBindingSource();
        source.Name = GetUniqueBindingSourceName("SqlSource");
        source.Path = source.Name;
        source.ItemTypeName = "SqlRow";
        source.Description = "Источник SQL Server. Укажите строку подключения и таблицу или SQL-запрос.";
        source.SourceKind = "SqlServer";
        source.SourceSchemaName = "dbo";
        source.SourceTableName = "";
        source.SourceQuery = "";
        StatusText = "Создан SQL BindingSource. Заполните строку подключения и нажмите «Подтянуть из БД».";
        RaiseBindingEditorProperties();
        return source;
    }

    [RelayCommand]
    private void CreateBindingSourceForSelectedControl()
    {
        if (SelectedControl is null || !SupportsDataBinding(SelectedControl))
        {
            StatusText = "Выберите DataGrid, чтобы создать BindingSource для него.";
            return;
        }

        BeginUndoBatch();
        try
        {
            var source = AddBindingSource();
            source.Name = GetUniqueBindingSourceName($"{SelectedControl.NameOrFallback()}Source");
            source.Path = source.Name;
            source.ItemTypeName = $"{SelectedControl.NameOrFallback()}Row";
            source.Description = "Источник создан из DataGrid data setup.";
            EnsureSampleFields(source);
            SelectedControl.BindingSourceId = source.Id;
            SelectedBindingSource = source;
            RaiseBindingEditorProperties();
            StatusText = $"BindingSource «{source.Name}» создан и подключен к {SelectedControl.NameOrFallback()}.";
        }
        finally
        {
            CommitUndoBatch();
        }
    }

    [RelayCommand]
    private void CreateColumnsFromSelectedBindingSource()
    {
        var source = SelectedBindingSourceForControl ?? SelectedBindingSource;
        if (source is null)
        {
            StatusText = "Сначала выберите или создайте BindingSource.";
            return;
        }

        BeginUndoBatch();
        try
        {
            if (source.Fields.Count == 0)
                EnsureSampleFields(source);

            var visibleIndex = 0;
            foreach (var field in source.Fields)
            {
                if (string.IsNullOrWhiteSpace(field.Header))
                    field.Header = string.IsNullOrWhiteSpace(field.Path) ? $"Column {visibleIndex + 1}" : field.Path;
                if (string.IsNullOrWhiteSpace(field.Width))
                    field.Width = "*";

                field.IsVisible = true;
                field.VisibleIndex = visibleIndex++;
            }

            if (SelectedControl is { Type: DesignerControlTypes.DataGrid } grid)
                grid.AutoGenerateColumns = false;

            RaiseBindingEditorProperties();
            NotifyDesignerStateChanged();
            StatusText = $"Колонки DataGrid подготовлены из BindingSource «{source.Name}».";
        }
        finally
        {
            CommitUndoBatch();
        }
    }

    [RelayCommand]
    private void OpenLogicForSelectedControl()
    {
        WorkspaceMode = WorkspaceModeLogic;
    }

    [RelayCommand]
    private void OpenBindingSourceEditor()
    {
        WorkspaceMode = WorkspaceModeData;
    }

    private static void EnsureSampleFields(BindingSourceModel source)
    {
        if (source.Fields.Count > 0)
            return;

        source.Fields.Add(new BindingFieldModel
        {
            Header = "Id",
