    private void InitializeWorkspaceFromActiveDocument(bool markAsSaved)
    {
        var workspace = _projectWorkspaceService.CreateWorkspace("Avalonia UI Project");
        var form = workspace.Project.Forms[0];
        form.Name = string.IsNullOrWhiteSpace(FormTitle) ? "MainWindow" : FormTitle;
        form.RelativePath = $"Forms/{form.DisplayName}.formdesigner.json";
        form.Document = CreateDocumentFileModel();
        var snapshot = JsonSerializer.Serialize(form.Document, JsonOptions);
        form.CurrentSnapshot = snapshot;
        form.SavedSnapshot = markAsSaved ? snapshot : "";
        form.IsDirty = !markAsSaved;

        Workspace = workspace;
        ActiveFormDocument = form;
        CurrentProjectPath = "";
        CurrentProject.DefaultNamespace = ResolveExportNamespace();
        CurrentProject.Settings.ReopenDocumentsOnStartup = ReopenLastWorkspaceOnStartup;
        CurrentProject.ExportProfiles[0].Namespace = ResolveExportNamespace();
        RefreshDocumentTabs();
        RebuildProjectExplorer();
        RaiseProjectWorkspaceProperties();
    }

    private void ApplyWorkspace(WorkspaceModel workspace, string? sourcePath, bool markAsSaved)
    {
        PersistActiveFormDocumentState(refreshProjectViews: false);
        _projectWorkspaceService.EnsureWorkspaceDefaults(workspace);

        foreach (var form in workspace.Project.Forms)
        {
            form.Document ??= new DesignerDocumentFileModel { FormTitle = form.DisplayName };
            if (string.IsNullOrWhiteSpace(form.Name))
                form.Name = string.IsNullOrWhiteSpace(form.Document.FormTitle) ? "Form" : form.Document.FormTitle;
            if (string.IsNullOrWhiteSpace(form.RelativePath))
                form.RelativePath = $"Forms/{form.DisplayName}.formdesigner.json";

            var snapshot = string.IsNullOrWhiteSpace(form.CurrentSnapshot)
                ? JsonSerializer.Serialize(form.Document, JsonOptions)
                : form.CurrentSnapshot;
            form.CurrentSnapshot = snapshot;
            if (markAsSaved || string.IsNullOrWhiteSpace(form.SavedSnapshot))
                form.SavedSnapshot = markAsSaved ? snapshot : form.SavedSnapshot;
            form.IsDirty = string.IsNullOrWhiteSpace(form.SavedSnapshot)
                ? !markAsSaved
                : !string.Equals(form.CurrentSnapshot, form.SavedSnapshot, StringComparison.Ordinal);
        }

        Workspace = workspace;
        CurrentProjectPath = sourcePath ?? "";
        var activeForm = CurrentProject.Forms.FirstOrDefault(form => string.Equals(form.Id, Workspace.Session.ActiveDocumentId, StringComparison.OrdinalIgnoreCase))
            ?? CurrentProject.Forms[0];
        if (!Workspace.Session.OpenDocumentIds.Contains(activeForm.Id))
            Workspace.Session.OpenDocumentIds.Insert(0, activeForm.Id);

        SetActiveForm(activeForm.Id, "ApplyWorkspace", persistCurrent: false);
        StatusText = $"Workspace loaded: {CurrentProjectDisplayName}";
        LogWorkspace(WorkspaceLogLevel.Info, OutputCategoryGeneral, StatusText, sourcePath ?? "");
    }

    private void ApplyFormDocument(DesignerFormDocument form, bool persistCurrent = true, bool restoreSessionSelection = true)
    {
        SetActiveForm(form.Id, "LegacyApplyFormDocument", persistCurrent);
    }

    public bool SetActiveForm(string? documentId, string reason, bool persistCurrent = true)
    {
        DumpInteractionState($"BeforeSetActiveForm:{reason}");

        if (_isInspectorInteractionActive)
        {
            TraceDocumentDebug(
                "INSPECTOR_INTERACTION_FORCED_END_BEFORE_FORM_SWITCH",
                $"operation=SetActiveForm; reason={reason}; target={documentId}; interaction={_inspectorInteractionKind}; depth={_inspectorInteractionDepth}",
                toOutput: true,
                warning: true);
            _isInspectorInteractionActive = false;
            _inspectorInteractionDepth = 0;
            _pendingInspectorRebuild = false;
            _isPendingInspectorRebuildScheduled = false;
            _pendingInspectorRebuildReason = "";
            _inspectorInteractionKind = "";
            OnPropertyChanged(nameof(IsInspectorInteractionActive));
        }

        if (_isEditingPropertyGrid)
        {
            TraceDocumentDebug(
                "EDIT_FORCED_END_BEFORE_FORM_SWITCH",
                $"operation=SetActiveForm; reason={reason}; target={documentId}; editing={_editingPropertyGridDocumentId}/{_editingPropertyGridControlId}/{_editingPropertyGridKey}",
                toOutput: true,
                warning: true);
            EndPropertyGridTextEdit();
        }

        if (persistCurrent)
            SaveActiveFormState(reason);

        var result = LoadActiveFormState(documentId, reason);
        DumpInteractionState($"AfterSetActiveForm:{reason}:result={result}");
        return result;
    }

    public DesignerFormDocument CreateNewForm()
    {
        DumpInteractionState("BeforeAddForm");
        TraceDocumentStateSnapshot("BeforeCreateNewForm", toOutput: false);
        SaveActiveFormState("CreateNewForm");
        var form = _projectDocumentService.AddForm(CurrentProject, "Form");
        Workspace.Session.OpenDocumentIds.RemoveAll(id => string.Equals(id, form.Id, StringComparison.OrdinalIgnoreCase));
        Workspace.Session.OpenDocumentIds.Add(form.Id);
        form.SavedSnapshot = "";
        form.IsDirty = true;
        RefreshFormsCollection();
        LoadActiveFormState(form.Id, "CreateNewForm");
        MarkExportCacheStale();
        RaiseDocumentStateProperties();
        RaiseProjectWorkspaceProperties();
        StatusText = $"Form added: {form.DisplayName}";
        LogWorkspace(WorkspaceLogLevel.Info, OutputCategoryGeneral, StatusText);
        DumpInteractionState("AfterAddForm");
        return form;
    }

    public bool OpenFormDocument(string formId)
    {
        return SetActiveForm(formId, "OpenFormDocument");
    }

    public void CloseFormDocument(string formId)
    {
        if (string.IsNullOrWhiteSpace(formId))
            return;

        if (string.Equals(formId, ActiveDocumentId, StringComparison.OrdinalIgnoreCase))
        {
            CloseActiveDocument();
            return;
        }

        Workspace.Session.OpenDocumentIds.RemoveAll(id => string.Equals(id, formId, StringComparison.OrdinalIgnoreCase));
        Workspace.Session.RecentlyClosedDocumentIds.RemoveAll(id => string.Equals(id, formId, StringComparison.OrdinalIgnoreCase));
        Workspace.Session.RecentlyClosedDocumentIds.Insert(0, formId);
        RefreshDocumentTabs();
        StatusText = "Document tab closed.";
    }

    private void SaveActiveFormState(string reason)
    {
        TraceDocumentDebug("SaveActiveFormState", $"reason={reason}", toOutput: false);
        PersistActiveFormDocumentState(refreshProjectViews: false);
    }

    private void ClearActiveDocumentTransientState(string reason)
    {
        TraceDocumentDebug("ClearActiveDocumentTransientState", $"reason={reason}; active={ActiveDocumentName}:{ActiveDocumentId}", toOutput: false);

        if (_isEditingPropertyGrid)
            EndPropertyGridTextEdit();

        _isPropertyGridLiveGesture = false;
        _hasPendingPropertyGridLiveRefresh = false;
        _propertyGridLiveGestureSessionId = "";
        _propertyGridLiveRefreshTimer.Stop();
        _hasDeferredPropertyGridRebuild = false;
        _deferredPropertyGridRebuildReason = "";
        _isInspectorInteractionActive = false;
        _inspectorInteractionDepth = 0;
        _pendingInspectorRebuild = false;
        _isPendingInspectorRebuildScheduled = false;
        _pendingInspectorRebuildReason = "";
        _inspectorInteractionKind = "";
        _propertyGridContextDocumentId = "";
        _propertyGridContextControlId = "";
        _propertyGridRowsByKey.Clear();
        _propertyGridRowsByContextKey.Clear();
        PropertyGridCategories.Clear();
        DescriptorCustomPropertyEditors.Clear();
        SelectedInteraction = null;
        SelectedBindingSource = null;
        SelectedLayoutGridRow = null;
        SelectedLayoutGridColumn = null;

        _isUpdatingStructureSelection = true;
        try
        {
            SelectedStructureItem = null;
        }
        finally
        {
            _isUpdatingStructureSelection = false;
        }

        ClearSelection();
        _canvasRenderedDocumentId = "";
        OnPropertyChanged(nameof(HasPropertyGridRows));
        OnPropertyChanged(nameof(HasNoPropertyGridRows));
    }

    private bool LoadActiveFormState(string? documentId, string reason)
    {
        if (string.IsNullOrWhiteSpace(documentId))
            return false;

        var form = CurrentProject.Forms.FirstOrDefault(item => string.Equals(item.Id, documentId, StringComparison.OrdinalIgnoreCase));
        if (form is null)
        {
            TraceDocumentDebug("LoadActiveFormState rejected", $"reason={reason}; missingDocument={documentId}", toOutput: true, warning: true);
            return false;
        }

        TraceDocumentDebug("SetActiveForm", $"reason={reason}; target={form.DisplayName}:{form.Id}; previous={ActiveFormDocument?.DisplayName ?? "-"}:{ActiveDocumentId}", toOutput: false);

        _isSwitchingActiveForm = true;
        try
        {
            ClearActiveDocumentTransientState($"BeforeLoadActiveForm:{reason}");
            ActiveFormDocument = form;
            Workspace.Session.ActiveDocumentId = form.Id;
            if (!Workspace.Session.OpenDocumentIds.Contains(form.Id))
                Workspace.Session.OpenDocumentIds.Add(form.Id);

            var document = form.Document ?? new DesignerDocumentFileModel { FormTitle = form.DisplayName };
            if (!string.IsNullOrWhiteSpace(form.CurrentSnapshot))
            {
                try
                {
                    document = JsonSerializer.Deserialize<DesignerDocumentFileModel>(form.CurrentSnapshot, JsonOptions)
                        ?? document;
                    form.Document = document;
                    TraceDocumentDebug(
                        "LoadActiveFormStateSnapshot",
                        $"reason={reason}; source=CurrentSnapshot; form={form.DisplayName}:{form.Id}; controls={document.Controls.Count}",
                        toOutput: false);
                }
                catch (Exception ex)
                {
                    TraceDocumentDebug(
                        "LoadActiveFormStateSnapshotFailed",
                        $"reason={reason}; form={form.DisplayName}:{form.Id}; error={ex.GetType().Name}: {ex.Message}; fallback=Document",
                        toOutput: true,
                        warning: true);
                }
            }

            ApplyDocument(
                document,
                CurrentProjectPath,
                markAsSaved: !form.IsDirty,
                resetDocumentSession: true,
                resetHistory: false,
                refreshEditorSurfaces: false);

            _undoStack.Clear();
            foreach (var snapshot in form.UndoSnapshots)
                _undoStack.Push(snapshot);

            _redoStack.Clear();
            foreach (var snapshot in form.RedoSnapshots)
                _redoStack.Push(snapshot);

            _currentSnapshot = string.IsNullOrWhiteSpace(form.CurrentSnapshot)
                ? JsonSerializer.Serialize(CreateDocumentFileModel(), JsonOptions)
                : form.CurrentSnapshot;
            _savedSnapshot = string.IsNullOrWhiteSpace(form.SavedSnapshot) && !form.IsDirty
                ? _currentSnapshot
                : form.SavedSnapshot;
            _lastHistoryMutationUtc = DateTime.UtcNow;

            ClearActiveDocumentTransientState($"AfterLoadActiveForm:{reason}");
            RefreshFormsCollection();
            RefreshDocumentTabs();
            RebuildProjectExplorer();
            RaiseProjectWorkspaceProperties();
            RaiseDocumentStateProperties();
            RebuildStructureTree();
            RebuildInspectorForActiveForm(reason);
            RebuildCanvasForActiveForm(reason);
            RefreshDiagnostics();
            if (IsCodeMode)
                GenerateXaml();
            else
                MarkExportCacheStale();
            StatusText = $"Active form: {form.DisplayName}";
            return true;
        }
        finally
        {
            _isSwitchingActiveForm = false;
        }
    }

    private void RebuildInspectorForActiveForm(string reason)
    {
        if (DeferInspectorRebuildIfNeeded("RebuildInspectorForActiveForm", reason))
            return;

        TraceDocumentDebug("RebuildInspectorForActiveForm", $"reason={reason}; active={ActiveDocumentName}:{ActiveDocumentId}", toOutput: false);
        RebuildPropertyGrid($"ActiveForm:{reason}");
        RaiseBindingEditorProperties();
        RaiseInteractionDesignerProperties();
        RaiseInteractionLookupProperties();
        RaiseActiveLayoutProperties();
    }

    private void RebuildCanvasForActiveForm(string reason)
    {
        TraceDocumentDebug("RebuildCanvasForActiveForm", $"reason={reason}; active={ActiveDocumentName}:{ActiveDocumentId}; controls={Controls.Count}", toOutput: false);
        DesignerChanged?.Invoke(this, EventArgs.Empty);
    }

    private void PersistActiveFormDocumentState(bool refreshProjectViews = true)
    {
        if (_isApplyingDocument || ActiveFormDocument is null)
            return;

        var form = ActiveFormDocument;
        form.Document = CreateDocumentFileModel();
        form.Name = string.IsNullOrWhiteSpace(form.Document.FormTitle) ? form.DisplayName : form.Document.FormTitle;
        var freshSnapshot = JsonSerializer.Serialize(form.Document, JsonOptions);
        _currentSnapshot = freshSnapshot;
        form.CurrentSnapshot = freshSnapshot;
        form.SavedSnapshot = _savedSnapshot;
        form.IsDirty = !string.Equals(form.CurrentSnapshot, form.SavedSnapshot, StringComparison.Ordinal);
        form.UndoSnapshots = _undoStack.Reverse().ToList();
        form.RedoSnapshots = _redoStack.Reverse().ToList();
        form.Zoom = EditorZoom;
        form.SelectedControlId = "";
        form.UpdatedUtc = DateTime.UtcNow;

        if (refreshProjectViews)
        {
            RefreshDocumentTabs();
            RebuildProjectExplorer();
            RaiseProjectWorkspaceProperties();
        }
    }

    private void RefreshDocumentTabs()
    {
        RefreshFormsCollection();
        _isSwitchingDocumentTabs = true;
        try
        {
            var openIds = Workspace.Session.OpenDocumentIds
                .Where(id => CurrentProject.Forms.Any(form => string.Equals(form.Id, id, StringComparison.OrdinalIgnoreCase)))
                .Distinct(StringComparer.OrdinalIgnoreCase)
                .ToList();
            if (ActiveFormDocument is not null && !openIds.Contains(ActiveFormDocument.Id))
                openIds.Insert(0, ActiveFormDocument.Id);
            if (openIds.Count == 0 && CurrentProject.Forms.Count > 0)
                openIds.Add(CurrentProject.Forms[0].Id);

            Workspace.Session.OpenDocumentIds = openIds;
            DocumentTabs.Clear();
            foreach (var id in openIds)
            {
                var form = CurrentProject.Forms.FirstOrDefault(item => string.Equals(item.Id, id, StringComparison.OrdinalIgnoreCase));
                if (form is null)
                    continue;

                var tab = new DesignerDocumentTabModel(form)
                {
                    IsActive = string.Equals(form.Id, ActiveFormDocument?.Id, StringComparison.OrdinalIgnoreCase)
                };
                DocumentTabs.Add(tab);
            }

            SelectedDocumentTab = DocumentTabs.FirstOrDefault(tab => tab.IsActive);
        }
        finally
        {
            _isSwitchingDocumentTabs = false;
        }

        OnPropertyChanged(nameof(HasMultipleDocuments));
        OnPropertyChanged(nameof(HasOpenDocuments));
        OnPropertyChanged(nameof(ActiveDocumentTitle));
        ScheduleEditorCommandRefresh();
    }

    private void RefreshFormsCollection()
    {
        Forms.Clear();
        foreach (var form in CurrentProject.Forms)
            Forms.Add(form);
    }

    private void RebuildProjectExplorer()
    {
        if (_isEditingPropertyGrid)
        {
            TraceDocumentDebug(
                "SKIPPED_DURING_PROPERTY_EDIT",
                "operation=RebuildProjectExplorer",
                toOutput: true,
                warning: true);
            return;
        }

        _isUpdatingProjectExplorerSelection = true;
        try
        {
            ProjectExplorerItems.Clear();
            var forms = CreateProjectFolder("Forms", "F", CurrentProject.Forms.Count);
            foreach (var form in CurrentProject.Forms)
            {
                forms.Children.Add(new ProjectExplorerItemModel
                {
                    Id = form.Id,
                    TargetId = form.Id,
                    ItemType = "Form",
                    Icon = "F",
                    Name = form.DisplayName,
                    Source = form,
                    IsActive = string.Equals(form.Id, ActiveFormDocument?.Id, StringComparison.OrdinalIgnoreCase)
                });
            }

            var assets = CreateProjectFolder("Assets", "A", CurrentProject.Assets.Count);
            foreach (var asset in CurrentProject.Assets)
            {
                assets.Children.Add(new ProjectExplorerItemModel
                {
                    Id = asset.Id,
                    TargetId = asset.Id,
                    ItemType = "Asset",
                    Icon = "A",
                    Name = asset.Name,
                    Source = asset
                });
            }

            var export = new ProjectExplorerItemModel
            {
                Id = "project-export",
                TargetId = "Export",
                ItemType = "Export",
                Icon = "EX",
                Name = "Export",
                Description = ExportPipelineCompactSummary,
                IsExpanded = false
            };

            AddEmptyPlaceholderIfNeeded(forms, "No forms yet.");
            AddEmptyPlaceholderIfNeeded(assets, "No assets yet.");

            ProjectExplorerItems.Add(forms);
            ProjectExplorerItems.Add(assets);
            ProjectExplorerItems.Add(export);
            SelectedProjectExplorerItem = null;
            SetProjectExplorerSelectionState(null);
        }
        finally
        {
            _isUpdatingProjectExplorerSelection = false;
        }

        RefreshOpenFormTargetForms();
        OnPropertyChanged(nameof(ProjectExplorerSummary));
        OnPropertyChanged(nameof(HasProjectAssets));
        OnPropertyChanged(nameof(HasProjectResources));
    }

    private ProjectExplorerItemModel? FindProjectExplorerItemById(string? targetId)
    {
        if (string.IsNullOrWhiteSpace(targetId))
            return null;

        return FlattenProjectExplorerItems(ProjectExplorerItems)
            .FirstOrDefault(item => string.Equals(item.TargetId, targetId, StringComparison.OrdinalIgnoreCase)
                || string.Equals(item.Id, targetId, StringComparison.OrdinalIgnoreCase));
    }

    private void RefreshOpenFormTargetForms()
    {
        var forms = CurrentProject.Forms
            .OrderBy(form => form.DisplayName, StringComparer.OrdinalIgnoreCase)
            .ToList();
        var signature = string.Join("|", forms.Select(form => $"{form.Id}:{form.DisplayName}"));

        if (string.Equals(_openFormTargetFormsSignature, signature, StringComparison.Ordinal)
            && OpenFormTargetForms.Count == forms.Count)
        {
            var isSame = true;
            for (var i = 0; i < forms.Count; i++)
            {
                if (ReferenceEquals(OpenFormTargetForms[i], forms[i]))
                    continue;

                isSame = false;
                break;
            }

            if (isSame)
            {
                OnPropertyChanged(nameof(HasOpenFormTargets));
                OnPropertyChanged(nameof(OpenFormTargetHint));
                return;
            }
        }

        OpenFormTargetForms = new ObservableCollection<DesignerFormDocument>(forms);
        _openFormTargetFormsSignature = signature;
        OnPropertyChanged(nameof(HasOpenFormTargets));
        OnPropertyChanged(nameof(OpenFormTargetHint));
    }

    private static ProjectExplorerItemModel CreateProjectFolder(string name, string icon, int count)
    {
        return new ProjectExplorerItemModel
        {
            Id = $"folder:{name}",
            TargetId = name,
            ItemType = "Folder",
            Icon = icon,
            Name = name,
            Count = count,
            IsExpanded = true
        };
    }

    private static void AddEmptyPlaceholderIfNeeded(ProjectExplorerItemModel folder, string text)
    {
        if (folder.Children.Count > 0)
            return;

        folder.Children.Add(new ProjectExplorerItemModel
        {
            Id = $"{folder.Id}:empty",
            TargetId = folder.TargetId,
            ItemType = "Empty",
            Icon = "",
            Name = text,
            Count = -1,
            IsExpanded = false
        });
    }

    private void SetProjectExplorerSelectionState(ProjectExplorerItemModel? selectedItem)
    {
        foreach (var item in FlattenProjectExplorerItems(ProjectExplorerItems))
            item.IsSelected = ReferenceEquals(item, selectedItem)
                || (!string.IsNullOrWhiteSpace(selectedItem?.Id)
                    && string.Equals(item.Id, selectedItem.Id, StringComparison.OrdinalIgnoreCase));
    }

    private static IEnumerable<ProjectExplorerItemModel> FlattenProjectExplorerItems(IEnumerable<ProjectExplorerItemModel> items)
    {
        foreach (var item in items)
        {
            yield return item;
            foreach (var child in FlattenProjectExplorerItems(item.Children))
                yield return child;
        }
    }

    private void NewProject()
    {
        var oldFormIds = CurrentProject.Forms.Select(form => form.Id).Where(id => !string.IsNullOrWhiteSpace(id)).ToList();
        var oldControlIds = CurrentProject.Forms
            .SelectMany(form => form.Document?.Controls ?? new List<DesignerControlFileModel>())
            .Select(control => control.Id)
            .Concat(Controls.Select(control => control.Id))
            .Where(id => !string.IsNullOrWhiteSpace(id))
            .Distinct(StringComparer.OrdinalIgnoreCase)
            .ToList();
        var oldProjectExplorerFormIds = GetProjectExplorerFormIds().ToList();
        var oldOpenedTabs = DocumentTabs.Select(tab => tab.DocumentId).Where(id => !string.IsNullOrWhiteSpace(id)).ToList();
        var oldProjectId = CurrentProject.Id;
#if DEBUG
        var oldObjectReferences = CaptureOldProjectWeakReferences();
#endif

        TraceDocumentDebug(
            "NEW_PROJECT_START",
            $"oldProjectId={oldProjectId}; oldProjectName={CurrentProjectDisplayName}; oldFormsCount={CurrentProject.Forms.Count}; oldFormIds={string.Join(",", oldFormIds)}; oldProjectExplorerFormIds={string.Join(",", oldProjectExplorerFormIds)}; oldOpenedTabs={string.Join(",", oldOpenedTabs)}; oldActiveFormId={ActiveDocumentId}; oldCanvasDocumentId={CanvasRenderedDocumentId}; oldSelectedControlId={SelectedControl?.Id ?? ""}; controls={CurrentProject.Forms.Sum(form => form.Document?.Controls.Count ?? 0) + Controls.Count}; dll={ImportedDllCatalog.Count}; dataSources={BindingSources.Count}",
            toOutput: true);

        ReportMemorySnapshot("BeforeNewProject", forceFullCollection: false);
        ResetApplicationStateForNewProject(oldFormIds, oldControlIds, "NewProject");
        ReportMemorySnapshot("AfterNewProjectReset", forceFullCollection: false);

        Workspace = _projectWorkspaceService.CreateWorkspace("Avalonia UI Project");
        CurrentProjectPath = "";
        var activeForm = CurrentProject.Forms[0];
        activeForm.Document = CreateDefaultDocumentFileModel("Form1");
        activeForm.Name = activeForm.Document.FormTitle;
        activeForm.RelativePath = $"Forms/{activeForm.DisplayName}.formdesigner.json";
        CurrentProject.DefaultNamespace = ResolveExportNamespace();
        CurrentProject.Settings.ReopenDocumentsOnStartup = ReopenLastWorkspaceOnStartup;
        CurrentProject.ExportProfiles[0].Namespace = ResolveExportNamespace();
        TraceDocumentDebug(
            "NEW_PROJECT_CREATE_NEW_FORM",
            $"newProjectId={CurrentProject.Id}; newFormId={activeForm.Id}; newFormName={activeForm.DisplayName}",
            toOutput: true);
        SetActiveForm(activeForm.Id, "NewProject", persistCurrent: false);
        AssertCleanNewProjectState(oldFormIds, oldControlIds, "NewProject");
#if DEBUG
        GC.Collect();
        GC.WaitForPendingFinalizers();
        GC.Collect();
        ReportMemorySnapshot("AfterNewProjectGc", forceFullCollection: false);
        CheckOldProjectWeakReferences(oldObjectReferences, "NewProject");
#endif
        TraceDocumentDebug(
            "NEW_PROJECT_CREATED",
            $"newProjectName={CurrentProjectDisplayName}; forms={CurrentProject.Forms.Count}; active={ActiveDocumentName}:{ActiveDocumentId}; selected={SelectedControl?.Name ?? "-"}:{SelectedControl?.Id ?? "-"}",
            toOutput: true);
        TraceDocumentDebug(
            "NEW_PROJECT_END",
            $"formsCount={CurrentProject.Forms.Count}; formIds={string.Join(",", CurrentProject.Forms.Select(form => form.Id))}; explorerFormIds={string.Join(",", GetProjectExplorerFormIds())}; openedTabs={string.Join(",", DocumentTabs.Select(tab => tab.DocumentId))}; activeFormId={ActiveDocumentId}; canvasDocumentId={CanvasRenderedDocumentId}; selectedControlId={SelectedControl?.Id ?? ""}",
            toOutput: true);
        StatusText = "New project created.";
        LogWorkspace(WorkspaceLogLevel.Info, OutputCategoryGeneral, StatusText);
    }

    private void ResetApplicationStateForNewProject(
        IReadOnlyCollection<string> oldFormIds,
        IReadOnlyCollection<string> oldControlIds,
        string reason)
    {
        TraceDocumentDebug(
            "NEW_PROJECT_RESET_STATE_START",
            $"reason={reason}; forms={CurrentProject.Forms.Count}; active={ActiveDocumentName}:{ActiveDocumentId}; selected={SelectedControl?.Name ?? "-"}:{SelectedControl?.Id ?? "-"}",
            toOutput: true);

        var previousApplyingDocument = _isApplyingDocument;
        var previousHistorySuspended = _isHistorySuspended;
        var previousSwitchingActiveForm = _isSwitchingActiveForm;
        var previousStructureTreeSuspended = _isStructureTreeRefreshSuspended;

        _isApplyingDocument = true;
        _isHistorySuspended = true;
        _isSwitchingActiveForm = true;
        _isStructureTreeRefreshSuspended = true;

        try
        {
            UnsubscribeDocumentEventHandlersForNewProject();
            ResetDocumentScopedRefreshState();
            StopDocumentRefreshTimersForNewProject();
            TraceDocumentDebug("NEW_PROJECT_CLEAR_STATE_START", $"reason={reason}", toOutput: true);

            var oldProjectFormIds = CurrentProject.Forms.Select(form => form.Id).Where(id => !string.IsNullOrWhiteSpace(id)).ToList();
            TraceDocumentDebug(
                "NEW_PROJECT_CLEAR_FORMS",
                $"beforeCount={CurrentProject.Forms.Count}; ids={string.Join(",", oldProjectFormIds)}",
                toOutput: true);
            CurrentProject.Forms.Clear();
            TraceDocumentDebug(
                "NEW_PROJECT_CLEAR_FORMS",
                $"afterCount={CurrentProject.Forms.Count}; ids={string.Join(",", CurrentProject.Forms.Select(form => form.Id))}",
                toOutput: true);

            TraceDocumentDebug(
                "NEW_PROJECT_CLEAR_DOCUMENT_SNAPSHOTS",
                $"beforeCount={oldProjectFormIds.Count}; ids={string.Join(",", oldProjectFormIds)}",
                toOutput: true);
            TraceDocumentDebug(
                "NEW_PROJECT_CLEAR_DOCUMENT_SNAPSHOTS",
                "afterCount=0; ids=",
                toOutput: true);

            ClearCollectionForNewProject(Controls, nameof(Controls));
            ClearCollectionForNewProject(BindingSources, nameof(BindingSources));
            ClearCollectionForNewProject(Interactions, nameof(Interactions));
            ClearCollectionForNewProject(SelectedControlIds, nameof(SelectedControlIds));
            ClearCollectionForNewProject(StructureTreeItems, nameof(StructureTreeItems));
            ClearCollectionForNewProject(PropertyGridCategories, nameof(PropertyGridCategories));
            ClearCollectionForNewProject(UndoRedoHistoryItems, nameof(UndoRedoHistoryItems));
            TraceDocumentDebug(
                "NEW_PROJECT_CLEAR_OPENED_TABS",
                $"beforeCount={DocumentTabs.Count}; ids={string.Join(",", DocumentTabs.Select(tab => tab.DocumentId))}",
                toOutput: true);
            ClearCollectionForNewProject(DocumentTabs, nameof(DocumentTabs));
            TraceDocumentDebug(
                "NEW_PROJECT_CLEAR_OPENED_TABS",
                $"afterCount={DocumentTabs.Count}; ids={string.Join(",", DocumentTabs.Select(tab => tab.DocumentId))}",
                toOutput: true);
            ClearCollectionForNewProject(Forms, nameof(Forms));
            TraceDocumentDebug(
                "NEW_PROJECT_CLEAR_PROJECT_EXPLORER",
                $"beforeFormNodeCount={GetProjectExplorerFormIds().Count()}; ids={string.Join(",", GetProjectExplorerFormIds())}",
                toOutput: true);
            ClearCollectionForNewProject(ProjectExplorerItems, nameof(ProjectExplorerItems));
            TraceDocumentDebug(
                "NEW_PROJECT_CLEAR_PROJECT_EXPLORER",
                $"afterFormNodeCount={GetProjectExplorerFormIds().Count()}; ids={string.Join(",", GetProjectExplorerFormIds())}",
                toOutput: true);
            ClearCollectionForNewProject(GeneratedFiles, nameof(GeneratedFiles));
            ClearCollectionForNewProject(GeneratedFileTreeNodes, nameof(GeneratedFileTreeNodes));
            ClearCollectionForNewProject(RequiredPackages, nameof(RequiredPackages));
            ClearCollectionForNewProject(ExportDiagnostics, nameof(ExportDiagnostics));
            ClearCollectionForNewProject(ImportedDllCatalog, nameof(ImportedDllCatalog));
            ClearCollectionForNewProject(FilteredImportedDllCatalog, nameof(FilteredImportedDllCatalog));
            ClearCollectionForNewProject(DescriptorCustomPropertyEditors, nameof(DescriptorCustomPropertyEditors));
            ClearCollectionForNewProject(LayoutGridRows, nameof(LayoutGridRows));
            ClearCollectionForNewProject(LayoutGridColumns, nameof(LayoutGridColumns));
            ClearCollectionForNewProject(Diagnostics, nameof(Diagnostics));

            SelectedControl = null;
            SelectedDocumentTab = null;
            SelectedProjectExplorerItem = null;
            SelectedStructureItem = null;
            SelectedInteraction = null;
            SelectedBindingSource = null;
            SelectedLayoutGridRow = null;
            SelectedLayoutGridColumn = null;
            SelectedGeneratedFile = null;
            SelectedGeneratedFileNode = null;
            ActiveFormDocument = null;

            _undoStack.Clear();
            _redoStack.Clear();
            _currentSnapshot = "";
            _savedSnapshot = "";
            _lastHistoryMutationUtc = DateTime.UtcNow;
            _clipboardDocument = null;
            _styleClipboard = null;
            _activeXamlWriter = null;
            _activeXamlExportContext = null;
            _activeXamlControlNodes = null;
            _activeXamlControlNameMap = null;
            _activeLayoutExportPlan = null;
            _exportNamespaceOverride = null;
            _exportWindowClassNameOverride = null;
            _exportViewModelClassNameOverride = null;
            _exportActiveFormIdOverride = null;
            _exportCacheDocumentSnapshotHash = "";
            _exportCacheSettingsSignature = "";
            _exportCacheGeneratedUtc = DateTime.MinValue;
            _exportChecklistItemsCache = Array.Empty<ExportChecklistItem>();
            CurrentExportResult = new ExportResult();
            CurrentExportBuildValidation = new ExportBuildValidationResult();
            GeneratedXaml = "";
            GeneratedCSharp = "";
            GeneratedBindingGuide = "";
            CurrentDocumentPath = "";
            CurrentProjectPath = "";
            ImportedDllSearchText = "";
            StructureSearchText = "";
            PropertyGridSearchText = "";
            _openFormTargetFormsSignature = "";
            OpenFormTargetForms = new ObservableCollection<DesignerFormDocument>();
            _controlDocumentIdsByControlId.Clear();
            _controlPropertySubscriptions.Clear();
            _structureTreeItemsByControlId.Clear();
            _propertyGridRowsByKey.Clear();
            _propertyGridRowsByContextKey.Clear();
            _previewRuntimeDiagnostics.Clear();
            _refreshOperationTimestamps.Clear();
            _lastCanvasWrapperCount = 0;
            _lastPreviewRowsCount = 0;
            _canvasRenderedDocumentId = "";
            DocumentSessionId = Guid.NewGuid().ToString("N");

            Workspace.Session.OpenDocumentIds.Clear();
            Workspace.Session.RecentlyClosedDocumentIds.Clear();
            Workspace.Session.ActiveDocumentId = "";
            Workspace.Session.SelectedProjectItemId = "";

            TraceDocumentDebug(
                "NEW_PROJECT_RESET_STATE_END",
                $"reason={reason}; forms={Forms.Count}; selected={SelectedControl?.Name ?? "-"}:{SelectedControl?.Id ?? "-"}; active={ActiveDocumentName}:{ActiveDocumentId}; inspector={PropertyGridContextDocumentId}/{PropertyGridContextControlId}; dll={ImportedDllCatalog.Count}; dataSources={BindingSources.Count}; oldFormsTracked={oldFormIds.Count}; oldControlsTracked={oldControlIds.Count}",
                toOutput: true);
        }
        finally
        {
            _isStructureTreeRefreshSuspended = previousStructureTreeSuspended;
            _isSwitchingActiveForm = previousSwitchingActiveForm;
            _isHistorySuspended = previousHistorySuspended;
            _isApplyingDocument = previousApplyingDocument;
        }
    }

    private void UnsubscribeDocumentEventHandlersForNewProject()
    {
        var unsubscribedControls = 0;
        foreach (var control in Controls.ToList())
        {
            control.PropertyChanged -= Control_PropertyChanged;
            unsubscribedControls++;
        }

        var detachedSources = 0;
        foreach (var source in BindingSources.ToList())
        {
            DetachBindingSource(source);
            detachedSources++;
        }

        var detachedInteractions = 0;
        foreach (var interaction in Interactions.ToList())
        {
            interaction.PropertyChanged -= Interaction_PropertyChanged;
            detachedInteractions++;
        }

        TraceDocumentDebug(
            "NEW_PROJECT_UNSUBSCRIBE_HANDLERS",
            $"controls={unsubscribedControls}; bindingSources={detachedSources}; interactions={detachedInteractions}",
            toOutput: true);
    }

    private void StopDocumentRefreshTimersForNewProject()
    {
        _propertyGridLiveRefreshTimer.Stop();
        _diagnosticsRefreshTimer.Stop();
        _exportChecklistRefreshTimer.Stop();
        _structureTreeSearchRefreshTimer.Stop();
        _editorCommandRefreshTimer.Stop();
        _isDiagnosticsRefreshScheduled = false;
        _isExportChecklistRefreshScheduled = false;
        _isStructureTreeSearchRefreshScheduled = false;
        _isEditorCommandRefreshScheduled = false;
        _scheduledDiagnosticsSessionId = "";
        _scheduledExportChecklistSessionId = "";
        _scheduledStructureSearchSessionId = "";
    }

    private void ClearCollectionForNewProject<T>(ICollection<T> collection, string name)
    {
        var oldCount = collection.Count;
        collection.Clear();
        TraceDocumentDebug(
            "NEW_PROJECT_CLEAR_COLLECTION",
            $"collection={name}; oldCount={oldCount}; newCount={collection.Count}",
            toOutput: false);
    }

    private void AssertCleanNewProjectState(
        IReadOnlyCollection<string> oldFormIds,
        IReadOnlyCollection<string> oldControlIds,
        string reason)
    {
        if (Forms.Count != 1
            || CurrentProject.Forms.Count != 1
            || ActiveFormDocument is null
            || !string.Equals(ActiveFormDocument.DisplayName, "Form1", StringComparison.OrdinalIgnoreCase)
            || SelectedControl is not null
            || SelectedControlIds.Count != 0
            || DocumentTabs.Count != 1
            || BindingSources.Count != 0
            || ImportedDllCatalog.Count != 0
            || FilteredImportedDllCatalog.Count != 0
            || _undoStack.Count != 0
            || _redoStack.Count != 0
            || Controls.Count != 0)
        {
            TraceDocumentDebug(
                "NEW_PROJECT_LEAKED_OLD_STATE",
                $"reason={reason}; location=post-state-shape; forms={Forms.Count}/{CurrentProject.Forms.Count}; active={ActiveDocumentName}:{ActiveDocumentId}; selected={SelectedControl?.Name ?? "-"}:{SelectedControl?.Id ?? "-"}; tabs={DocumentTabs.Count}; controls={Controls.Count}; dataSources={BindingSources.Count}; dll={ImportedDllCatalog.Count}; undo={_undoStack.Count}; redo={_redoStack.Count}",
                toOutput: true,
                warning: true);
        }

        var leakedFormIds = oldFormIds
            .Where(id => CurrentProject.Forms.Any(form => string.Equals(form.Id, id, StringComparison.OrdinalIgnoreCase))
                || Forms.Any(form => string.Equals(form.Id, id, StringComparison.OrdinalIgnoreCase))
                || DocumentTabs.Any(tab => string.Equals(tab.DocumentId, id, StringComparison.OrdinalIgnoreCase))
                || Workspace.Session.OpenDocumentIds.Any(openId => string.Equals(openId, id, StringComparison.OrdinalIgnoreCase))
                || string.Equals(Workspace.Session.ActiveDocumentId, id, StringComparison.OrdinalIgnoreCase)
                || string.Equals(ActiveDocumentId, id, StringComparison.OrdinalIgnoreCase))
            .ToList();

        foreach (var oldFormId in leakedFormIds)
        {
            TraceDocumentDebug(
                "NEW_PROJECT_LEAKED_OLD_STATE",
                $"reason={reason}; oldFormId={oldFormId}; location=forms/tabs/session/active",
                toOutput: true,
                warning: true);
        }

        foreach (var oldFormId in oldFormIds)
        {
            var foundIn = new List<string>();
            if (CurrentProject.Forms.Any(form => string.Equals(form.Id, oldFormId, StringComparison.OrdinalIgnoreCase)))
                foundIn.Add(nameof(CurrentProject.Forms));
            if (Forms.Any(form => string.Equals(form.Id, oldFormId, StringComparison.OrdinalIgnoreCase)))
                foundIn.Add(nameof(Forms));
            if (DocumentTabs.Any(tab => string.Equals(tab.DocumentId, oldFormId, StringComparison.OrdinalIgnoreCase)))
                foundIn.Add(nameof(DocumentTabs));
            if (Workspace.Session.OpenDocumentIds.Any(openId => string.Equals(openId, oldFormId, StringComparison.OrdinalIgnoreCase)))
                foundIn.Add(nameof(Workspace.Session.OpenDocumentIds));
            if (string.Equals(Workspace.Session.ActiveDocumentId, oldFormId, StringComparison.OrdinalIgnoreCase))
                foundIn.Add(nameof(Workspace.Session.ActiveDocumentId));
            if (string.Equals(ActiveDocumentId, oldFormId, StringComparison.OrdinalIgnoreCase))
                foundIn.Add(nameof(ActiveDocumentId));
            if (GetProjectExplorerFormIds().Any(id => string.Equals(id, oldFormId, StringComparison.OrdinalIgnoreCase)))
                foundIn.Add(nameof(ProjectExplorerItems));

            TraceDocumentDebug(
                "NEW_PROJECT_LEAK_CHECK",
                $"oldFormId={oldFormId}; foundIn={string.Join(",", foundIn)}; result={(foundIn.Count == 0 ? "clean" : "leaked")}",
                toOutput: false,
                warning: foundIn.Count > 0);
            if (foundIn.Count > 0)
            {
                TraceDocumentDebug(
                    "NEW_PROJECT_LEAKED_OLD_FORM_STATE",
                    $"reason={reason}; oldFormId={oldFormId}; foundIn={string.Join(",", foundIn)}",
                    toOutput: true,
                    warning: true);
            }
        }

        var leakedControlIds = oldControlIds
            .Where(id => Controls.Any(control => string.Equals(control.Id, id, StringComparison.OrdinalIgnoreCase))
                || SelectedControlIds.Any(selectedId => string.Equals(selectedId, id, StringComparison.OrdinalIgnoreCase))
                || string.Equals(SelectedControl?.Id, id, StringComparison.OrdinalIgnoreCase)
                || PropertyGridCategories.SelectMany(category => category.Rows).Any(row => string.Equals(row.ContextControlId, id, StringComparison.OrdinalIgnoreCase))
                || _controlDocumentIdsByControlId.ContainsKey(id)
                || _controlPropertySubscriptions.Contains(id))
            .ToList();

        foreach (var oldControlId in leakedControlIds)
        {
            TraceDocumentDebug(
                "NEW_PROJECT_LEAKED_OLD_STATE",
                $"reason={reason}; oldControlId={oldControlId}; location=controls/selection/property-grid/subscriptions",
                toOutput: true,
                warning: true);
        }
    }

#if DEBUG
    private sealed record TrackedWeakReference(string Kind, string Id, WeakReference Reference);

    private List<TrackedWeakReference> CaptureOldProjectWeakReferences()
    {
        var references = new List<TrackedWeakReference>();
        references.Add(new TrackedWeakReference("Project", CurrentProject.Id, new WeakReference(CurrentProject)));

        foreach (var form in CurrentProject.Forms)
        {
            references.Add(new TrackedWeakReference("Form", form.Id, new WeakReference(form)));
            if (form.Document is not null)
                references.Add(new TrackedWeakReference("Document", form.Id, new WeakReference(form.Document)));

            foreach (var control in form.Document?.Controls ?? Enumerable.Empty<DesignerControlFileModel>())
                references.Add(new TrackedWeakReference("SerializedControl", control.Id, new WeakReference(control)));
        }

        foreach (var control in Controls)
            references.Add(new TrackedWeakReference("RuntimeControl", control.Id, new WeakReference(control)));

        foreach (var source in BindingSources)
            references.Add(new TrackedWeakReference("BindingSource", source.Id, new WeakReference(source)));

        foreach (var row in PropertyGridCategories.SelectMany(category => category.Rows))
            references.Add(new TrackedWeakReference("PropertyRow", $"{row.ContextDocumentId}/{row.ContextControlId}/{row.Key}", new WeakReference(row)));

        return references;
    }

    private void CheckOldProjectWeakReferences(IReadOnlyList<TrackedWeakReference> references, string reason)
    {
        var alive = references
            .Where(item => item.Reference.IsAlive)
            .GroupBy(item => item.Kind)
            .Select(group => $"{group.Key}:{group.Count()}")
            .ToList();

        TraceDocumentDebug(
            "OLD_PROJECT_OBJECTS_STILL_ALIVE",
            $"reason={reason}; tracked={references.Count}; alive={(alive.Count == 0 ? "none" : string.Join(", ", alive))}",
            toOutput: true,
            warning: alive.Count > 0);
    }
#endif

    private IEnumerable<string> GetProjectExplorerFormIds()
    {
        return FlattenProjectExplorerItems(ProjectExplorerItems)
            .Where(item => string.Equals(item.ItemType, "Form", StringComparison.OrdinalIgnoreCase))
            .Select(item => item.TargetId)
            .Where(id => !string.IsNullOrWhiteSpace(id));
    }

    private void AddForm()
    {
        CreateNewForm();
    }

    private void AddResource()
    {
        var resource = _projectResourceService.AddResourceDictionary(CurrentProject);
        MarkWorkspaceStructureChanged();
        RebuildProjectExplorer();
        RaiseProjectWorkspaceProperties();
        StatusText = $"Resource added: {resource.RelativePath}";
        LogWorkspace(WorkspaceLogLevel.Info, OutputCategoryGeneral, StatusText);
    }

    public DesignerAssetModel? RegisterProjectAsset(string? sourcePath)
    {
        if (string.IsNullOrWhiteSpace(sourcePath))
            return null;

        var asset = _projectAssetService.RegisterAsset(CurrentProject, sourcePath);
        MarkWorkspaceStructureChanged();
        RebuildProjectExplorer();
        RaiseProjectWorkspaceProperties();
        StatusText = $"Asset imported: {asset.RelativePath}";
        LogWorkspace(WorkspaceLogLevel.Info, OutputCategoryGeneral, StatusText, sourcePath);
        return asset;
    }

    private void CloseActiveDocument()
    {
        if (ActiveFormDocument is null || Workspace.Session.OpenDocumentIds.Count <= 1)
            return;

        PersistActiveFormDocumentState(refreshProjectViews: false);
        var closingId = ActiveFormDocument.Id;
        Workspace.Session.OpenDocumentIds.RemoveAll(id => string.Equals(id, closingId, StringComparison.OrdinalIgnoreCase));
        Workspace.Session.RecentlyClosedDocumentIds.RemoveAll(id => string.Equals(id, closingId, StringComparison.OrdinalIgnoreCase));
        Workspace.Session.RecentlyClosedDocumentIds.Insert(0, closingId);

        var nextId = Workspace.Session.OpenDocumentIds.FirstOrDefault();
        var next = CurrentProject.Forms.FirstOrDefault(form => string.Equals(form.Id, nextId, StringComparison.OrdinalIgnoreCase))
            ?? CurrentProject.Forms.FirstOrDefault(form => !string.Equals(form.Id, closingId, StringComparison.OrdinalIgnoreCase));
        if (next is not null)
            SetActiveForm(next.Id, "CloseActiveDocument", persistCurrent: false);

        StatusText = "Document tab closed.";
    }

    private void ReopenClosedDocument()
    {
        var id = Workspace.Session.RecentlyClosedDocumentIds.FirstOrDefault();
        if (string.IsNullOrWhiteSpace(id))
            return;

        var form = CurrentProject.Forms.FirstOrDefault(item => string.Equals(item.Id, id, StringComparison.OrdinalIgnoreCase));
        if (form is null)
        {
            Workspace.Session.RecentlyClosedDocumentIds.RemoveAt(0);
            return;
        }

        Workspace.Session.RecentlyClosedDocumentIds.RemoveAt(0);
        if (!Workspace.Session.OpenDocumentIds.Contains(form.Id))
            Workspace.Session.OpenDocumentIds.Add(form.Id);
        SetActiveForm(form.Id, "ReopenClosedDocument");
        StatusText = $"Reopened: {form.DisplayName}";
    }

    private void OpenProjectSettings()
    {
        IsLeftDockOpen = true;
        WorkspaceMode = WorkspaceModeData;
        SelectedProjectExplorerItem = ProjectExplorerItems.FirstOrDefault();
        StatusText = $"Project settings: {CurrentProjectDisplayName}, namespace {CurrentProject.DefaultNamespace}.";
    }

    private void OpenExplorer()
    {
        IsLeftDockOpen = true;
        WorkspaceMode = WorkspaceModeDesign;
        StatusText = "Project Explorer opened.";
    }

    [RelayCommand]
    private void SwitchDocument(DesignerDocumentTabModel? tab)
    {
        if (tab is null)
            return;

        var form = CurrentProject.Forms.FirstOrDefault(item => string.Equals(item.Id, tab.DocumentId, StringComparison.OrdinalIgnoreCase));
        if (form is null || string.Equals(form.Id, ActiveFormDocument?.Id, StringComparison.OrdinalIgnoreCase))
            return;

        SetActiveForm(form.Id, "SwitchDocument");
    }

    [RelayCommand]
    private void CloseDocumentTab(DesignerDocumentTabModel? tab)
    {
        if (tab is null)
            return;

        if (string.Equals(tab.DocumentId, ActiveFormDocument?.Id, StringComparison.OrdinalIgnoreCase))
        {
            CloseActiveDocument();
            return;
        }

        Workspace.Session.OpenDocumentIds.RemoveAll(id => string.Equals(id, tab.DocumentId, StringComparison.OrdinalIgnoreCase));
        Workspace.Session.RecentlyClosedDocumentIds.RemoveAll(id => string.Equals(id, tab.DocumentId, StringComparison.OrdinalIgnoreCase));
        Workspace.Session.RecentlyClosedDocumentIds.Insert(0, tab.DocumentId);
        RefreshDocumentTabs();
        StatusText = "Document tab closed.";
    }

    [RelayCommand]
    private void OpenProjectExplorerItem(ProjectExplorerItemModel? item)
    {
        if (item?.Source is DesignerFormDocument form)
        {
            OpenFormDocument(form);
            return;
        }

        if (item is { IsFolder: true })
        {
            item.IsExpanded = !item.IsExpanded;
            StatusText = item.Children.Count == 0
                ? "This virtual project folder is empty."
                : $"{item.DisplayName}: {(item.IsExpanded ? "expanded" : "collapsed")}.";
            return;
        }

        if (item?.Source is DesignerAssetModel asset)
        {
            PreviewProjectAsset(item);
            return;
        }

        if (item?.ItemType == "Export")
        {
            WorkspaceMode = WorkspaceModeCode;
            GenerateXaml();
            StatusText = "Export Pipeline opened.";
            return;
        }

        if (item?.Source is DesignerResourceModel resource)
        {
            WorkspaceMode = WorkspaceModeCode;
            GenerateXaml();
            SelectedGeneratedFile = GeneratedFiles.FirstOrDefault(file => string.Equals(file.Path, resource.RelativePath, StringComparison.OrdinalIgnoreCase))
                ?? SelectedGeneratedFile;
            StatusText = $"Resource selected: {resource.RelativePath}";
        }
    }

    [RelayCommand]
    private void DuplicateProjectExplorerItem(ProjectExplorerItemModel? item)
    {
        if (item?.Source is not DesignerFormDocument form)
            return;

        PersistActiveFormDocumentState(refreshProjectViews: false);
        var duplicate = _projectDocumentService.DuplicateForm(CurrentProject, form);
        Workspace.Session.OpenDocumentIds.Add(duplicate.Id);
        SetActiveForm(duplicate.Id, "DuplicateForm", persistCurrent: false);
        MarkWorkspaceStructureChanged();
        StatusText = $"Form duplicated: {duplicate.DisplayName}";
    }

    [RelayCommand]
    private void DeleteProjectExplorerItem(ProjectExplorerItemModel? item)
    {
        if (item?.Source is DesignerAssetModel asset)
        {
            CurrentProject.Assets.Remove(asset);
            MarkWorkspaceStructureChanged();
            StatusText = $"Asset removed: {asset.DisplayPath}";
            return;
        }

        if (item?.Source is not DesignerFormDocument form)
            return;

        if (!_projectDocumentService.DeleteForm(CurrentProject, form.Id))
        {
            StatusText = "Project must contain at least one form.";
            return;
        }

        Workspace.Session.OpenDocumentIds.RemoveAll(id => string.Equals(id, form.Id, StringComparison.OrdinalIgnoreCase));
        Workspace.Session.RecentlyClosedDocumentIds.RemoveAll(id => string.Equals(id, form.Id, StringComparison.OrdinalIgnoreCase));
        var next = CurrentProject.Forms.FirstOrDefault();
        if (next is not null)
        {
            if (!Workspace.Session.OpenDocumentIds.Contains(next.Id))
                Workspace.Session.OpenDocumentIds.Add(next.Id);
            SetActiveForm(next.Id, "DeleteForm", persistCurrent: false);
        }

        MarkWorkspaceStructureChanged();
        StatusText = $"Form deleted: {form.DisplayName}";
    }

    [RelayCommand]
    private void PreviewProjectAsset(ProjectExplorerItemModel? item)
    {
        if (item?.Source is not DesignerAssetModel asset)
            return;

        StatusText = $"Asset selected: {asset.DisplayPath}";
        LogWorkspace(WorkspaceLogLevel.Info, OutputCategoryGeneral, StatusText, asset.SourcePath);
    }

    [RelayCommand]
    private void BeginRenameProjectExplorerItem(ProjectExplorerItemModel? item)
    {
        if (item is null || !item.CanRename)
            return;

        item.IsRenaming = true;
        SelectedProjectExplorerItem = item;
        StatusText = $"Renaming: {item.DisplayName}";
    }

    [RelayCommand]
    private void CommitProjectExplorerRename(ProjectExplorerItemModel? item)
    {
        if (item is null)
            return;

        item.IsRenaming = false;
        if (item.Source is DesignerFormDocument form)
        {
            form.Document.FormTitle = form.DisplayName;
            form.RelativePath = $"Forms/{form.DisplayName}.formdesigner.json";
            UpdateOpenFormTargetNames(form.Id, form.DisplayName);
            if (string.Equals(form.Id, ActiveFormDocument?.Id, StringComparison.OrdinalIgnoreCase))
                FormTitle = form.DisplayName;
        }

        MarkWorkspaceStructureChanged();
        StatusText = $"Renamed: {item.DisplayName}";
    }

