        RightDockPanelWidth = Math.Clamp(layout.RightPanelWidth <= 0 ? 340 : layout.RightPanelWidth, 260, 560);
        DiagnosticsPaneHeight = Math.Clamp(layout.BottomPanelHeight <= 0 ? 180 : layout.BottomPanelHeight, 140, 520);
