    [RelayCommand]
    private void AddGridRowDefinition()
    {
        MutateGridDefinitions(isRows: true, definitions =>
        {
            definitions.Add(LayoutDefinitionToken.Star(1));
            return definitions;
        });
    }

    [RelayCommand]
    private void AddGridColumnDefinition()
