            }
        }

        var extraInteractionHandlers = exportableInteractions
            .Where(item => !string.Equals(item.EventName, InteractionModel.EventButtonClick, StringComparison.OrdinalIgnoreCase))
            .ToList();

        if (hasSelectionInteractions)
        {
