    private void Interactions_CollectionChanged(object? sender, NotifyCollectionChangedEventArgs e)
    {
        if (e.OldItems is not null)
        {
            foreach (InteractionModel interaction in e.OldItems)
                interaction.PropertyChanged -= Interaction_PropertyChanged;
        }

        if (e.NewItems is not null)
        {
            foreach (InteractionModel interaction in e.NewItems)
                interaction.PropertyChanged += Interaction_PropertyChanged;
        }

        if (_isApplyingDocument)
            return;

        RaiseInteractionDesignerProperties();
        RebuildPropertyGrid();
        NotifyDesignerStateChanged();
    }

    private void Interaction_PropertyChanged(object? sender, PropertyChangedEventArgs e)
    {
        if (_isApplyingDocument)
            return;

        if (sender is InteractionModel interaction
            && e.PropertyName is nameof(InteractionModel.ActionType))
        {
            ApplyInteractionActionDefaults(interaction, FindControlByName(interaction.SourceControlName));
        }

        if (sender is InteractionModel openFormInteraction
            && e.PropertyName is nameof(InteractionModel.ActionType) or nameof(InteractionModel.TargetFormId))
        {
            EnsureOpenFormInteractionDefaults(openFormInteraction);
        }

        RaiseInteractionDesignerProperties();
        RebuildPropertyGrid();
        NotifyDesignerStateChanged();
    }

    private static bool IsLayoutDefinitionProperty(string? propertyName)
    {
        return propertyName is nameof(DesignControlModel.ChildLayoutMode)
            or nameof(DesignControlModel.LayoutOrientation)
            or nameof(DesignControlModel.LayoutSpacing)
            or nameof(DesignControlModel.Columns)
            or nameof(DesignControlModel.Rows)
            or nameof(DesignControlModel.GridColumnDefinitions)
            or nameof(DesignControlModel.GridRowDefinitions)
            or nameof(DesignControlModel.ShowGridLines)
            or nameof(DesignControlModel.ParentId)
            or nameof(DesignControlModel.GridRow)
            or nameof(DesignControlModel.GridColumn)
            or nameof(DesignControlModel.GridRowSpan)
            or nameof(DesignControlModel.GridColumnSpan)
            or nameof(DesignControlModel.StackOrder);
    }

    partial void OnSelectedInteractionChanged(InteractionModel? value)
    {
        if (_trackedSelectedInteractionForLogic is not null)
            _trackedSelectedInteractionForLogic.PropertyChanged -= SelectedInteractionForLogic_PropertyChanged;
        _trackedSelectedInteractionForLogic = value;
        if (_trackedSelectedInteractionForLogic is not null)
            _trackedSelectedInteractionForLogic.PropertyChanged += SelectedInteractionForLogic_PropertyChanged;

        if (value is not null)
            EnsureOpenFormInteractionDefaults(value);
        _isSyncingLogicTemplateDraft = true;
        try
        {
            LogicTemplateDraft = value?.TextTemplate ?? "";
        }
        finally
        {
            _isSyncingLogicTemplateDraft = false;
        }
        IsLogicTemplateEditing = false;
        if (value is not null)
        {
            TraceDocumentDebug(
                "LOGIC_UI_ACTION_SELECTED",
                $"action={value.Id}; source={value.SourceControlName}; target={value.TargetControlName}; event={value.EventName}; actionType={value.ActionType}",
                toOutput: false);
        }
        RaiseInteractionDesignerProperties();
    }

    private void SelectedInteractionForLogic_PropertyChanged(object? sender, PropertyChangedEventArgs e)
    {
        if (sender is not InteractionModel interaction)
            return;

        if (e.PropertyName == nameof(InteractionModel.TextTemplate) && !_isSyncingLogicTemplateDraft && !IsLogicTemplateEditing)
        {
            _isSyncingLogicTemplateDraft = true;
            try
            {
                LogicTemplateDraft = interaction.TextTemplate;
            }
            finally
            {
                _isSyncingLogicTemplateDraft = false;
            }
        }

        TraceDocumentDebug(
            "LOGIC_UI_VALIDATION_STATE_CHANGED",
            $"action={interaction.Id}; property={e.PropertyName}; status={LogicTemplateValidationText}; errors={LogicTemplateInvalidPlaceholders.Count}",
            toOutput: false);
        RaiseInteractionDesignerProperties();
    }

